WITH payload AS (SELECT $archive_payload$[{"id":"79f3a294-7b92-52fe-9f10-1e631ef8e45b","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترش -مضايقة امرأة -التحرش بالطالبات جنسي ا -مشروعية التعزير بالقرينة -التعزير بالسجن واجللد .","document_number":"34192316","case_number":"34128829","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/20","year":"1434","subject":"حترش -مضايقة امرأة -التحرش بالطالبات جنسي ا -مشروعية التعزير بالقرينة -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34192316 :‬تاريخه ‪ 1434/04/20 :‬هـ‬\n                    ‫رقم الدعوى ‪34128829 :‬‬\n               ‫رقم قرار التصديق من محكمة‬\n   ‫االستئناف‪ 34342769:‬تاريخه‪1434/10/27:‬هـ‬\n\n\n  ‫حتــرش ‪ -‬مضايقــة امــرأة ‪ -‬التحــرش بالطالبــات جنســي ًا ‪ -‬مشــروعية‬\n                            ‫التعزيــر بالقرينــة ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n  ‫ا بتهمــة ) رواه أبــو‬ ‫‪ ( -1‬حبــس النبــي ‪ -‬صلــى اهلل عليــه وســلم ‪ -‬رج ـ ً‬\n                       ‫داود ‪ ،‬والترمــذي ‪ ،‬وقــال الترمــذي‪ :‬حســن صحيــح ‪.‬‬\n                                      ‫‪ -2‬القاعدة الفقهية ( األصل البراءة ) ‪.‬‬\n                   ‫‪ -3‬ما ذكره أهل العلم من مشروعية التعزير بالقرينة ‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي العــام علــى املدعــى عليــه باتهامــه بإســتغالل عملــه حارسـ ًا‬\n  ‫ملدرســة بالتحــرش بالطالبــات جنســي ًا ‪ ،‬حيــث تقــدم أحــد املواطنــن‬\n  ‫ببــاغ يفيــد عــن قيــام املدعــى عليــه والــذي يعمــل حارس ـ ًا يف مــدارس‬\n  ‫البنــات االبتدائيــة ‪ ،‬بالتحــرش بابنتــه ‪ ،‬بعــد أن قــام بإنزالهــا صباحـ ًا ‪،‬‬\n  ‫وأنــه قــام بتقبيلهــا وملــس دبرهــا وطلــب املدعــي العــام تعزيــر املدعــى عليه‬\n  ‫لقــاء مــا نســب إليــه ‪ ،‬أنكــر املدعــى عليــه مــا جــاء بدعــوى املدعــي العــام‬\n  ‫ســوى أنــه أبقاهــا عنــده حتــى حضــور إحــدى الطالبــات ملــا أحضرهــا‬\n  ‫والدهــا مبكــرا ‪ ،‬ثــم جــرى االطــاع علــى أوراق املعاملــة فوجــد مــن‬\n  ‫ضمنهــا قضيــة حتــرش بحــق املدعــى عليــه و بعــرض ذلــك علــى املدعــى‬\n\n                                                                                          ‫‪116‬‬\n\f      ‫عليــه قــال‪ :‬وقعــت عليهــا ظنـ ًا منــي أنــه تنــازل فتبــن بعــد ذلــك أنــه إقــرار‬\n      ‫يف صحــة التحــرش يف القضيــة القدميــة ‪ ،‬وأنــا أمــي ال أقــرأ وال أكتــب ‪.‬‬\n      ‫ـاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن و‬         ‫بنـ ً‬\n      ‫اجللــد لقــاء توجيــه تهمــة القرينــة بحــق التحــرش بطفلــة مــع التوصيــة بنقل‬\n      ‫عملــه إلــى عمــل ال عالقــة لــه بالنســاء ‪ ،‬قــرر املدعــى عليــه االعتــراض‬\n      ‫بالئحــة و املدعــي العــام االعتــراض بــدون الئحــة ‪ ،‬ثــم قنــع وكيــل‬\n           ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬            ‫املدعــى عليــه باحلكــم ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم (‪ )........‬وتاريــخ ‪1434/03/17‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم (‪ )........‬وتاريــخ ‪ 1434/03/17‬ه ـ ففــي يــوم االثنــن‬\n      ‫املوافــق‪ 1434/04/15‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 : 15‬وفيهــا‬\n      ‫قــدم املدعــي العــام الئحــة دعــوى عامــة ضــد (‪ 59 )........‬ســنة ‪ ،‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ( ‪ ) .....‬محصــن ‪ ،‬يقيــم مبدينــة‬\n      ‫الريــاض موقــوف بتاريــخ ‪1434/2/16‬ه ـ وأحيــل للســجن العــام مبوجــب‬\n      ‫أمر اإلحالة ومتديد التوقيف رقم هـ را‪22354/3/‬وتاريخ‪1434/3/2‬هـ‬\n                      ‫اســتنادا للمــادة رقــم ‪ 113‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬‬\n      ‫حيــث إنــه بتاريــخ ‪1434/2/16‬ه ـ تقــدم املواطــن ‪ .....‬ببــاغ مفــاده قيــام‬\n      ‫املذكــور والــذي يعمــل حارســا للمدرســة التــي تدرس بها ابنتــه ‪ ...‬البالغة‬\n      ‫مــن العمــر ‪ 7‬ســنوات بالتحــرش بهــا يــوم الثالثــاء املوافــق ‪1434/2/12‬هـ‬\n      ‫بعــد أن قــام بإنزالهــا صبــاح ذلــك اليــوم باكــرا وانــه قــام بتقبيلهــا وملــس‬\n\n‫‪117‬‬\n\f‫دبرهــا وقبلهــا وباســتنطاق الطفلــة ‪ ...‬ذكــرت بأنــه عندمــا قــام والدهــا‬\n‫بإيصالهــا للمدرســة صباحــا ويف وقــت مبكــر لــم يكــن يف املدرســة‬\n‫احــد قــام املذكــور برفعهــا وتقبيلهــا علــى فمهــا وقــام بلمــس عورتهــا‬\n‫مــن اخللــف واألمــام وانــه قــام بفعــل ذلــك يف غرفتــه وأضافــت بأنــه‬\n‫ســبق أن فعــل ذلــك قبــل هــذه املــرة وباســتجواب املذكــور ذكــر بــأن‬\n‫املدعــي قــام بإحضــار ابنتــه باكــرا ولــم يكــن باملدرســة أحــدا فقــام‬\n‫بفتــح األبــواب لهــا وإضــاءة األنــوار وإدخالهــا لداخــل املدرســة إال أنهــا‬\n‫عنــد دخولهــا وعــدم مشــاهدتها ألحــد بداخــل املدرســة جعلهــا تبكــي‬\n‫وتعــود إليــه فجعلهــا تنتظــر معــه عنــد بوابــة املدرســة حلــن قــدوم احــد مــن‬\n‫الطالبــات وأضــاف بأنــه ســبق وان تقــدم احــد أوليــاء األمــور قبــل ســنه‬\n‫عليــه بدعــوى مماثلــه وبالبحــث عــن الدعــوى الســابقة عليــه تبــن قيامــه‬\n‫بضــم إحــدى الطالبــات وتقبيلهــا ولعــدم وجاهــة الســير يف الدعــوى مت‬\n‫حفــظ أوراق تلــك القضيــة اســتنادا للمــادة رقــم ‪ 62‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة وأســفرت إجــراءات التحقيــق عــن اتهامــه باســتغالل عملــه‬\n                            ‫حارســا ملدرســة بالتحــرش بالطالبــات جنســيا ‪.‬‬\n                                                 ‫وذلك لألدلة والقرائن التالية‪:‬‬\n           ‫‪ .1‬ملا جاء يف أقواله املدونة مبلف االستجواب املرفق لفه (‪. )6‬‬\n                      ‫‪ .2‬وجود سوابق مماثلة عليه ترجح قيامه بهذا العمل‪.‬‬\n                   ‫وببحث سوابقه اتضح عدم وجود سوابق مسجله عليه ‪.‬‬\n‫وحيــث إن مــا اقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــه‪ .‬وبــاهلل‬\n                                                                           ‫التوفيــق‬\n‫وبعــرض ذلــك علــى املدعــى عليــه أنكــر الدعــوى جملــة وتفصيال فجرى‬\n\n\n                                                                                        ‫‪118‬‬\n\f      ‫ســؤاله هــل بينــك وبــن والــد البنــت خصومــة فقــال أنــا ال أعرفــه وإمنــا‬\n      ‫أحضرهــا والدهــا ذات يــوم يف وقــت مبكــر فقمــت بفتــح بــاب املدرســة‬\n      ‫لهــا فخرجــت تبكــي مــن اخلــوف فأجلســتها عنــد بــاب املدرســة حتــى‬\n      ‫جــاء الطالبــات واإلداريــات هكــذا أجــاب فجــرى ســؤاله هــل ســبق أن‬\n      ‫حترشــت بطالبــة فقــال ال فجــرى ســؤاله ذكــرت يف أقوالــك ص ‪ 4‬لفــة‬\n      ‫أن هنــاك دعــوى ســابقة يف حتــرش ضــد طالبــة فقــال يف العــام الســابق‬\n      ‫صــدرت قضيــة حتــرش أنــا بــريء منهــا فقــام والــد الطالبــة بكتابــة‬\n      ‫ورقــة وقــال إنهــا تنــازل وطلــب منــي التوقيــع عليهــا فوقعــت وتفأجــات‬\n      ‫أن فيهــا إقــرار ًا منــي بأنــي قمــت بضــم ابنتــه وتقبيلهــا وأنــا أمــي ال أقــرأ‬\n      ‫وال أكتــب هكــذا أجــاب كمــا جــرى االطــاع علــى أقــوال الطفلــة ‪...‬‬\n      ‫ذات ســبع ســنوات واملــدون يف ‪ 2 / 27‬واملتضمــن أن والدهــا أحضرهــا‬\n      ‫للمدرســة باكــر ًا ولــم يكــن يف املدرســة أحــد وأن حــارس املدرســة‬\n      ‫قــام برفعهــا وتقبليهــا علــى فمهــا وملــس عورتهــا مــن األمــام واخللــف يف‬\n      ‫غرفتــه وأنــه قــام بفعــل هــذا مــن قبــل أ ‪ .‬ه ـ كمــا جــرى االطــاع لفــة (‬\n      ‫‪ ) 7‬علــى صــورة القضيــة التــي فيهــا إفــادة االدعــاء العــام إقــرار املدعــى‬\n      ‫عليــه بضــم طالبــة ذات عمــر اثنــي عشــر ســنة وتقبيلهــا فبنــاء علــى مــا‬\n      ‫ســلف مــن الدعــوى واإلجابــة وألن األصــل البــراءة ولقيــام القرائــن الدالــة‬\n      ‫علــى تهمــة التحــرش املذكــور وهــي إقــراره بوجــود ســابقة التحــرش‬\n      ‫الــذي اعتــذر بعــدم قراءتــه ومــا جــاء يف أقــوال الطفلــة ونفيــه العــداوة‬\n      ‫مــع والدهــا أو معرفتــه وملــا جــاء يف أقــوال مديــرة املدرســة الــواردة يف‬\n      ‫التحقيــق ص ‪ 5‬لفــة ( ‪ ) 8‬أن املدعــى عليــه قــد نقــل لســوء أخالقــه وأن‬\n      ‫عليــه عــدة شــكاوى وملشــروعية التعزيــر بالقرينــة كمــا حبــس النبــي‬\n      ‫ا تهمــة رواه أبــو داود وقــال الترمــذي حســن‬     ‫صلــى اهلل عليــه وســلم رجـ ً‬\n\n\n‫‪119‬‬\n\f‫صحيــح ولكبــر ســن املدعــى عليــه ولكــون مــن وقــع عليــه التحــرش‬\n‫مــن القاصــرات فإنــه لــم يثبــت لــدي إدانــة املدعــى عليــه بالتحــرش‬\n‫بطفلــة وإمنــا قامــت عليــه القرينــة وحكمــت عليــه لقــاء ذلــك بســجنه‬\n‫أربعــة أشــهر وجلــده ســبعني جلــدة وأوصــي بنقلــه إلــى عمــل ال عالقــة‬\n‫لــه بالنســاء وبعرضــه عليهمــا قــرر املدعــى عليــه االعتــراض بالئحــة‬\n‫اعتراضيــة وأفهــم بالنظــام وقــرر املدعــي العــام االعتــراض مكتفي ـ ًا‬\n‫بالئحــة الدعــوى وكان النطــق باحلكــم يف ‪ 1434 / 4 / 15‬ه ـ وأغلقــت‬\n‫اجللســة الســاعة التاســعة والنصــف وعليــه جــرى التوقيــع وصلــى اهلل على‬\n                                  ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض ففــي يــوم الســبت املوافــق‪ 1434/06/10‬ه ـ افتتحــت اجللســة‬\n‫الســاعة الثامنــة وفيهــا حضــر (‪ )........‬يحمــل ســجل مدنــي رقــم ( ‪....‬‬\n‫) وكيــل املدعــى عليــه ‪ .... /‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل مبحافظــة الدرعيــة برقــم (‪ )........‬و التاريــخ ‪1434/03/21 :‬ه ـ‬\n‫املخــول لــه فيهــا حــق املرافعــة و املدافعــة و اإلقــرار و اإلنــكار قبــول‬\n‫احلكــم و نفيهــا ‪ ...‬إلــخ و قــرر قناعــة موكلــه باحلكــم و تراجعــه عــن‬\n‫االعتــراض و عليــه جــرى التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                         ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا د (‪ )........‬القاضــي يف احملكمــة‬\n‫اجلزائيــة بالريــاض ففــي يــوم الثالثــاء ‪1434/08/09‬ه ـ افتتحــت اجللســة‬\n‫الســاعة الثامنــة و الربــع و قــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n‫بقــرار املالحظــة رقــم ‪ ....‬يف ‪1434/07/10‬ه ـ واملتضمــن بعــد املقدمــة‬\n‫أنــه « بدراســة القــرار وصــورة ضبطــه و أوراق املعاملــة لوحــظ باألكثرية‬\n\n\n                                                                                     ‫‪120‬‬\n\f      ‫أن فضيلتــه لــم يرفــق صــورة كاملــة لضبــط القضيــة و ال بــد مــن ذلــك‬\n      ‫إلجــراء مــا يلــزم «و جواب ـ ًا علــى ذلــك فقــد مت إرفــاق صــورة كاملــة‬\n      ‫القضيــة وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                          ‫ّ‬       ‫لضبــط‬\n                                                            ‫حــرر يف ‪1434/08/09‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة‬\n      ‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪....‬‬\n      ‫وتاريــخ ‪1434/9/16‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضي‬\n      ‫باحملكمــة الشــيخ‪ /‬د‪ .... .‬املســجل برقــم ‪ ...‬وتاريــخ ‪1434/4/20‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضد ‪ ....‬التهامه باســتغالل عمله بالتحرش‬\n      ‫علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون و‬\n      ‫مفصــل بــه و حيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي واحلقــه بالقــرار وصــورة‬\n      ‫ـاء علــى قرارنــا رقــم ‪ .....‬وتاريــخ ‪1434/7/10‬ه ـ قررنــا‬          ‫ضبطــه بنـ ً‬\n      ‫باألكثريــة املصادقــة علــى احلكــم أخيــراً‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                                            ‫نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪121‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":116,"source_page_end":121,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d77dee008c5ca299d495a317987d1db8270e8703e8e4f0e98fd6b6c7cb2f0540","normalized_text_hash":"3cc734454d909ee21dd45367000064ce58205ceab760baeb44dfe06db6b7fe19","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p116-34192316"},{"id":"3baa4357-8f29-5e97-bd06-7db23f87df69","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترش -مضايقة امرأة -إقامة عالقة محرمة -خلوة -إرسال رسائل بذيئة -التغرير بفتاة -اإلنسان مسؤول عما حتت يده - التعزير بالسجن و اجللد وأخذ التعهد.","document_number":"34330734","case_number":"34136208","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/14","year":"1434","subject":"حترش -مضايقة امرأة -إقامة عالقة محرمة -خلوة -إرسال رسائل بذيئة -التغرير بفتاة -اإلنسان مسؤول عما حتت يده - التعزير بالسجن و اجللد وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34330734 :‬تاريخه ‪1434/10/14 :‬هـ‬\n     ‫رقم الدعوى ‪ 34136208 :‬رقم قرار التصديق‬\n            ‫من محكمة االستئناف‪34354716:‬‬\n                       ‫تاريخه‪1434/11/19:‬هـ‬\n\n\n  ‫حتــرش ‪ -‬مضايقــة امــرأة ‪ -‬إقامــة عالقــة محرمــة ‪ -‬خلــوة ‪ -‬إرســال‬\n  ‫رســائل بذيئــة ‪ -‬التغريــر بفتــاة ‪ -‬اإلنســان مســؤول عمــا حتــت يــده ‪-‬‬\n                             ‫التعزيــر بالســجن و اجللــد وأخــذ التعهــد‪.‬‬\n\n\n\n\n                                     ‫قاعدة ( اإلنسان مسؤول عما حتت يده ) ‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي العــام علــى املدعــى عليــه بإقامــة عالقــة محرمــة مــع فتــاة‬\n  ‫ال متــت لــه بصلــة شــرعية و اخللــوة بهــا و مضايقتهــا و إزعاجهــا و إرســال‬\n  ‫رســائل بذيئــة و فاضحــة و غيــر الئقــة و التغريــر بهــا ‪ ،‬حيــث تقدمــت‬\n  ‫فتــاة بشــكوى لهيئــة األمــر باملعــروف والنهــي عــن املنكــر ‪ ،‬تتضمــن‬\n  ‫أنهــا تعرفــت علــى املدعــى عليــه ‪ ،‬ويظهــر عليــه عالمــات التديــن ‪،‬‬\n  ‫وقــد وعدهــا بالــزواج ‪ ،‬وقــام باخللــوة بهــا ‪ ،‬وابتزازهــا ‪ ،‬وكان يرســل‬\n  ‫لهــا رســائل علــى جوالهــا ‪ ،‬وباإلطــاع علــى الرســائل وجــد عــدد مــن‬\n  ‫الرســائل التــي حتتــوي علــى كلمــات بذيئــة ‪ ،‬وفاضحــة ‪ ،‬وغيــر الئقــة‬\n  ‫‪ ،‬وقــد أقــر املدعــى عليــه بإرســال رســائل نصيــة للفتــاة وطلــب املدعــي‬\n  ‫العــام تعزيــر املدعــى عليــه لقــاء مــا نســب إليــه ‪ ،‬أنكــر املدعــى عليــه‬\n  ‫مــا جــاء بدعــوى املدعــي العــام ســوى أنــه دفــع لهــا مبلغ ـ ًا مالي ـ ًا حلاجتهــا‬\n\n                                                                                              ‫‪122‬‬\n\f      ‫وط ِلــب مــن املدعــي العــام بينتــه علــى دعــواه ‪ ،‬فقــرر أنــه ليــس لديــه إال‬ ‫ُ‬\n      ‫مــا جــاء يف أوراق املعاملــة ‪ ،‬فجــرى االطــاع عليهــا فوجــد مــن ضمنهــا‬\n      ‫‪ :‬رســائل بذيئــة و غيــر الئقــة صــادرة مــن اجلــوال الــذي كان بحــوزة‬\n      ‫املدعــى عليــه إلــى جــوال الفتــاة ‪ ،‬و بعــرض ذلــك علــى املدعــى عليــه ‪:‬‬\n      ‫صــادق علــى أن اجلــوال لــه و لكــن أنكــر إرســاله هــذه الرســائل ‪ ،‬كما‬\n      ‫وجــد مــن ضمنهــا إقــرار املدعــى عليــه حتقيقــا بإرســال رســائل خادشــه‬\n      ‫للحيــاء جلــوال الفتــاة املشــتكية وبعرضــه علــى املدعــى عليــه صــادق علــى‬\n      ‫صــدور اإلقــرار منــه ‪ ،‬و دفــع بأنــه لــم يتــم قــراءة الرســائل عليــه ‪ ،‬بنــاء‬\n      ‫ملــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد و‬\n      ‫وأخــذ التعهــد عليــه بعــد تكــرار مــا حصــل لقــاء إدانتــه مبــا نســب إليــه‬\n      ‫يف دعــوى املدعــي العــام ســوى اخللــوة بهــا‪ ،‬قنــع املدعــى عليــه باحلكــم ‪،‬‬\n      ‫وقــرر املدعــي العــام اعتراضــه علــى احلكــم مكتفي ـ ًا بالئحــة الدعــوى‬\n                                        ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬        ‫ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بتبــوك برقــم ‪ 34136208‬وتاريــخ ‪1434/03/23‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34723136‬وتاريــخ ‪1434/03/23‬ه ـ ففــي يــوم‬\n      ‫اخلميــس املوافــق ‪ 1434/10/08‬ه ـ حضــر املدعــي العام (‪ )........‬اجلنســية‬\n      ‫مبوجــب ســجل مدنــي رقــم (‪ )........‬واملعمــد مــن مرجعــه مبوجــب اخلطــاب‬\n      ‫رقــم ‪ 17276‬يف ‪1434/9/9‬ه ـ وحضــر حلضــوره (‪ )........‬البالــغ من العمر‬\n      ‫‪ 36‬عامـ ًا ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم (‪ )........‬وبالرجــوع‬\n\n‫‪123‬‬\n\f‫للمعاملــة وجدتهــا مشــتملة علــى الئحــة دعــوى عامــة ضــد علــي املذكــور‬\n‫وفيهــا أنــه بتاريــخ ‪1433/10/10‬ه ـ تقدمــت فتــاة بشــكوى لهيئــة األمــر‬\n‫باملعــروف والنهــي عــن املنكــر مفادهــا أنهــا تعرفــت علــى املدعــى عليــه‬\n‫ويظهــر عليــه عالمــات التديــن وعدهــا بالــزواج يف بدايــة عالقتهمــا إلــى‬\n‫أن اســتمرت العالقــة وقــد قــام املدعــى عليــه باخللــوة بهــا و ابتزازهــا‬\n‫حســب ادعائهــا وكان يرســل لهــا رســائل عبــر جوالــه رقــم ( ‪ )...‬إلــى‬\n‫جوالهــا فتــم االتصــال علــى املدعــى عليــه مــن قبــل هيئــة األمــر باملعــروف‬\n‫لطلــب حضــوره فرفــض وقــام بإغــاق هاتفــه اجلــوال فتمــت مخاطبة جهة‬\n‫عملــه لكونــه يعمــل عســكري يف القــوات املســلحة باملنطقــة الشــمالية‬\n‫الغربيــة إلحضــاره ووردت إفادتهــم بــأن املدعــى عليــه متغيــب عــن عملــه‬\n‫مــن تاريــخ ‪1433/10/21‬ه ـ ‪.‬وبتاريــخ ‪1433/12/27‬ه ـ مت مشــاهدة‬\n‫املدعــى عليــه مــن قبــل أعضــاء هيئــة األمــر باملعــروف بحــي الصاحليــة‬\n‫بالقــرب مــن مركــز هيئــة اخلالديــة فتــم التنســيق مــع الدوريــات األمنيــة‬\n‫والقبــض عليــه وإحالتــه ملركــز شــرطة احلمــراء وباالطــاع علــى جــوال‬\n‫الفتــاة عثــر علــى رســائل بلــغ عددهــا (‪ )37‬ســبعة وثالثــن رســالة واردة‬\n‫مــن جــوال املدعــى عليــه رقــم (‪ )...‬إلــى جــوال الفتــاة واتضــح بأنهــا‬\n‫رســائل حتتــوي علــى كلمــات بذيئــة وفاضحــه وغيــر الئقــة وقــد مت‬\n‫تفريــغ الرســائل الــواردة يف محضــر خــاص مت إرفاقــه بــأوراق القضيــة‬\n‫لفــة رقــم (‪ -5‬إلــى ‪ )8‬كمــا مت االطــاع علــى جــواالت املدعــى عليــه ولــم‬\n‫يتضــح وجــود شــيء يفيــد القضيــة كمــا مت متكــن الفتــاة مــن االطــاع‬\n‫علــى جــواالت املدعــى عليــه وأفــادت بأنهــا ليســت هــي اجلــواالت التــي‬\n‫كانــت معــه أثنــاء العالقــة وبســماع أقــوال املدعــى عليــه ‪ ... /‬مــن قبــل‬\n‫رجــل الضبــط اجلنائــي مبركــز الشــرطة أقــر بأنــه قــام بإرســال رســائل‬\n\n\n                                                                                      ‫‪124‬‬\n\f      ‫نصيــة جلــوال الفتــاة وأفــاد بــأن الفتــاة املذكــورة اتصلــت عليــه يف شــهر‬\n      ‫رجــب عــام ‪1432‬ه ـ وكانــت تســأله عــن الســنة والشــيعة وبعدهــا قامــت‬\n      ‫بإزعاجــه كمــا أفــاد بأنــه كان بينــه وبــن الفتــاة اتصــاالت ورســائل‬\n      ‫نصيــة وأنــه ال يوجــد لديــه رســائل تخــص الفتــاة كمــا أفــاد بأنــه قــام‬\n      ‫بإعطائهــا مبلغـ ًا ماليـ ًا وقــدره (‪ )1000‬ألــف ريــال يف نهايــة عــام ‪1432‬ه ـ‬\n      ‫عنــد ســوق ( ‪ ) ...‬وبســماع أقــوال الفتــاة ‪ ... /‬لــدى جهــة التحقيــق أفــادت‬\n      ‫بأنهــا تعرفــت علــى املدعــى عليــه يف ســوق (‪ )...‬وبعدهــا اســتمرت العالقة‬\n      ‫بينهمــا وكان مينيهــا بالــزواج وبعــد ذلــك حصلــت مشــكلة بينهمــا وقــام‬\n      ‫ال صوتي ـ ًا ســوف توافينــا‬  ‫بتهديدهــا بنشــر صورهــا وأن لديهــا تســجي ً‬\n      ‫بــه وأفــادت بــأن الصــوت رديء جــد ًا قــد ال يفهــم منــه شــيء ‪ -‬كمــا‬\n      ‫أفــادت بأنــه لــم يرســل لهــا صــورا أو مقاطــع فيديــو بــل أرســل لهــا رســائل‬\n      ‫فيهــا تهديــد وأنهــا قامــت مبســحها مــن جهازهــا وحتــى تاريخــه لــم تقــم‬\n      ‫الفتــاة بإحضــار مــا يثبــت االبتــزاز ولــم تتجــاوب يف احلضــور رغــم محاولــة‬\n      ‫طلبهــا أكثــر مــن مــرة عــن طريــق االتصــال عليهــا وعــن طريــق التنســيق‬\n      ‫مــع هيئــة األمــر باملعــروف كمــا أنــه يف حــن ضبــط إفادتهــا لــدى جهــة‬\n      ‫التحقيــق لــم تســتطع اجللــوس يف مكتــب التحقيــق ســوى نصــف ســاعة‬\n      ‫وأفــادت بأنهــا خائفــة مــن الفضيحــة عنــد ذويهــا وقامــت باخلــروج مــن‬\n      ‫مكتــب التحقيــق وباســتجواب املدعــى عليــه ‪ ... /‬لــدى جهــة التحقيــق‬\n      ‫أقــر بــأن الرســائل الــواردة مبحضــر تفريــغ الرســائل مرســلة مــن جوالــه‬\n      ‫إلــى جــوال الفتــاة وأفــاد بــأن هــذه الرســائل صــدرت بصيغــة مبالغــة وأن‬\n      ‫بعــض الرســائل لــم يقــم بإرســالها ويعتقــد أن بعــض زمالئــه أرســلها وأنــه‬\n      ‫ال يســتطيع إحضــار زمالئــه وأنــه أيض ـ ًا ال يذكرهــم وأفــاد بأنــه لــم‬\n      ‫يــرى الفتــاة إال مــرة واحــدة بالليــل وهــي بعباءتهــا وال يعــرف جســمها‬\n\n\n‫‪125‬‬\n\f‫كمــا أفــاد بــأن الفتــاة أخــذت رقمــه مــن جريــدة الوســيلة واتصلــت عليــه‬\n‫العــام املاضــي يف شــهر رجــب تطلــب منــه جــوا ًال بالتقســيط فذكــر لهــا‬\n‫بأنــه البــد لهــا مــن إحضــار كفيــل أو محــرم فلــم تســتطع أن حتضــر ثــم‬\n‫قامــت مبراســلته واالتصــال عليــه لغــرض إقامــة عالقــة معــه كمــا أفــاد‬\n‫بأنــه يتحاشــاها ولكنهــا أكثــرت عليــه يف االتصــاالت والرســائل ثــم‬\n‫طلبــت منــه مبلغ ـ ًا مالي ـ ًا كســلفة فقــام بإيصــال املبلــغ لهــا عنــد ســوق‬\n‫( ‪ ) ...‬واســتلمت املبلــغ بيدهــا وكان برفقتهــا فتــاة أخــرى تدعــي أنهــا‬\n‫أختهــا واســتمرت علــى هــذا احلــال حتــى دخــل الســجن بقضيــة شــيك يف‬\n‫شــهر رجــب لعــام ‪1433‬ه ـ وخــرج يف شــهر شــوال مــن نفــس العــام ومنــذ‬\n‫دخولــه إلــى الســجن وإلــى اآلن لــم تقــم الفتــاة مبراســلته أو االتصــال بــه‬\n‫كمــا أفــاد بــأن ســبب دعــوى الفتــاة عليــه الرســائل املرفقــة بــاألوراق‬\n‫وقــد أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه ‪ ... /‬بإقامــة‬\n‫عالقــة محرمــة مــع فتــاة ال متــت لــه بصلــة شــرعية واخللــوة بهــا ومضايقتهــا‬\n‫وإزعاجهــا وإرســال رســائل بذيئــة وفاضحــه وغيــر الئقــة لهــا والتغريــر‬\n                                           ‫بهــا وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ -1‬اعترافــه ‪-‬املنــوه عنــه ‪ -‬املــدون علــى الصفحــة رقــم ( ‪ )2-1‬مــن دفتــر‬\n‫االســتدالل املرفــق لفــة رقــم (‪ )1‬واملــدون علــى اللفــات املرفقــة رقــم (‪-25‬‬\n                                                                             ‫‪)27-26‬‬\n‫‪ -2‬محضــر هيئــة األمــر باملعــروف والنهــي عــن املنكــر املرفــق لفــة رقــم‬\n                                                                           ‫( ‪)14-13‬‬\n   ‫‪ -3‬محضر تفريغ الرسائل ‪ -‬املنوه عنه ‪ -‬املرفق لفة رقم (‪-5‬إلى‪)8 -‬‬\n‫‪ -4‬محضــر الدوريــات األمنيــة املرفــق لفــة رقــم (‪ )16‬وحيــث أن مــا أقــدم‬\n                        ‫عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n\n\n                                                                                          ‫‪126‬‬\n\f      ‫لــذا أطلــب‪ -1 :‬إثبــات مــا أســند إليــه ‪ -2‬احلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫رادعــة لــه وزاجــرة لغيــره ‪ -3‬تشــديد العقوبــة عليــه لكونــه غــرر بهــا‬\n                         ‫مبظهــر التديــن (علم ـ ًا بــأن احلــق اخلــاص ال زال قائــم) ‪.‬‬\n      ‫وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه مــا ذكــره املدعــي‬\n      ‫العــام مــن أننــي قابلــت الفتــاة وأعطيتهــا ألــف ريــال عنــد ســوق ‪ ...‬وأن‬\n      ‫اجلــوال املذكــور يف الدعــوى جوالــي وعائــد لــي فصحيــح وهــو خــاص‬\n      ‫باملكتــب ويســتخدمه كذلــك موظفــي املكتــب وأمــا مــا ذكــره مــن‬\n      ‫قيامــي بإقامــة عالقــة محرمــة مــع فتــاة ال متــت لــي بصفــة شــرعية واخللــوة‬\n      ‫بهــا ومضايقتهــا وإزعاجهــا وإرســال رســائل بذيئــة وفاضحــة وغيــر الئقــة‬\n      ‫لهــا والتغريــر بهــا فغيــر صحيــح والصحيــح أن هــذه الفتــاة اتصلــت بــي‬\n      ‫تريــد أن تشــتري بالتقســيط فذكــرت لهــا أنــه البــد مــن إحضــار كفيــل‬\n      ‫أو معــرف للمــرأة فأصبحــت تلــح وتكثــر االتصــال وذكــرت لــي بأنهــا‬\n      ‫محتاجــة فأعطيتهــا ألــف ريــال عنــد ســوق ‪ ...‬وقــد كان بصحبتهــا‬\n      ‫امــرأة أخــرى وبعدهــا بفتــرة حضــرت للمكتــب وأعطــت العامــل قــدر‬\n      ‫فيــه دجــاج مطبــوخ فأحضــره لــي وال أعلــم مــا املناســبة فقــرأت عليــه‬\n      ‫وطلبــت منــه أن يرميــه ألن ريحتــه منتنــه وخشــيت أن يكــون فيــه‬\n      ‫ســحر وأصبحــت تكثــر االتصــال علــي بشــأن هــذا القــدر وال أعلــم‬\n      ‫ســبب شــكواها ضــدي وأعتقــد أنهــا تريــد املــال منــي هكــذا أجــاب‬\n      ‫وبعــرض مــا جــاء يف إجابتــه علــى املدعــي العــام قــال الصحيــح مــا جــاء يف‬\n      ‫دعــواي وبطلــب البينــة منــه قــال بينتــي مــا جــاء يف الئحــة الدعــوى وأوراق‬\n      ‫املعاملــة هكــذا قــرر ورفعــت اجللســة للدراســة والتأمــل ويف يــوم األربعــاء‬\n      ‫املوافــق‪ 1434/10/14‬ه ـ حضــر املدعــي العــام واملدعــى عليــه وبدراســة‬\n      ‫أوراق املعاملــة وجــدت علــى اللفــات مــن ( ‪ )8-5‬محضــر تفريــغ رســائل‬\n\n\n‫‪127‬‬\n\f‫معــد مــن قبــل هيئــة األمــر باملعــروف والنهــي عــن املنكــر وجــاء فيــه متــت‬\n‫مشــاهدة رســائل واردة علــى جــوال الفتــاة املهــددة مــن جــوال رقــم ( ‪)...‬‬\n‫وهــي خادشــه للحيــاء ومدونــه يف ضبــط القضيــة وحتــت هــذا احملضــر‬\n‫توقيــع منســوب لعضــوي الهيئــة ‪ ...‬و ‪ ...‬وبعــرض ذلــك علــى املدعــى عليــه‬\n‫قــال صحيــح أن اجلــوال املذكــور يف احملضــر جوالــي ولكنــه خــاص‬\n‫باملكتــب وأننــي أرســلت الرســالة التــي حتتــوي علــى رحــم اهلل أســد‬\n‫الســنة وكذلــك الرســالة التــي حتتــوي علــى أبشــتري لــك قــدر جديــد‬\n‫وأمــا بقيــت الرســائل فــا أذكرهــا هكــذا أجــاب كمــا وجــدت علــى‬\n‫الصفحــة الثانيــة مــن اللفــة األولــى حتقيقــا مــع املدعــى عليــه وفيــه‬\n‫إقــرار بإرســال رســائل خادشــة للحيــاء علــى جــوال الفتــاة وعليــه توقيــع‬\n‫بالبصمــة منســوب إليــه وبعرضــه عليــه قــال صحيــح أننــي أقــررت بذلــك‬\n‫ولكــن لــم يتــم علــي قــراءة الرســائل هكــذا أجــاب فنظــرا إلــى مــا دون‬\n‫مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه مبقابلــة الفتــاة وإعطائهــا‬\n‫مبلــغ مالــي وإقــرار بــأن اجلــوال الــذي صــدرت منــه الرســائل جلــوال الفتــاة‬\n‫جوالــه وملــا جــاء يف محضــر الرســائل املــدون مضمونــه أعــاه وألن‬\n‫اإلنســان مســئول عمــا حتــت يــده وبنــاء علــى جميــع مــا تقــدم فقــد ثبــت‬\n‫لــدي إدانــة املدعــى عليــه بإقامــة عالقــة محرمــة مــع فتــاة ال متــت لــه بصلــة‬\n‫شــرعية ومضايقتهــا وإزعاجهــا وإرســال رســائل بذيئــة وفاضحــة وغيــر‬\n‫الئقــة والتغريــر بهــا ولــم يثبــت لــدي إدانتــه باخللــوة بهــا وقــررت تعزيــره‬\n‫بجلــده ســبعني جلــدة دفعــة واحــدة وحبســه ملــدة شــهرين يحتســب منهــا‬\n‫فتــرة إيقافــه علــى ذمــة القضيــة وأخــذ التعهــد عليــه بعــدم تكــرار مــا‬\n‫حصــل منــه ومبــا ذكــر حكمــت فقــرر احملكــوم عليــه قناعتــه بــه ولــم‬\n‫يقنــع بــه املدعــي العــام معلــا ذلــك بقلــة احلكــم وطلــب متييــزه مكتفيــا‬\n\n\n                                                                                          ‫‪128‬‬\n\f      ‫بالئحــة الدعــوى عــن الالئحــة االعتراضيــة فأجبتــه لطلبــه وســيتم بعــث‬\n      ‫كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم حســب‬\n      ‫املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه‬\n                                                ‫وســلم ‪ .‬حــرر يف ‪1434/10/14‬ه ـ‬\n      ‫احلمد هلل وحده وبعد فقد اطلعنـا نحن قـضـاة الدائـرة اجلزائية الثانية يف‬\n      ‫محكمــة االســتئناف مبنطقــة تبــوك علــى املعاملــة الــواردة من احملكمة‬\n      ‫اجلزائيــة بتبــوك برقــم ‪ 342270742‬وتاريــخ ‪1434/10/18‬هـ ـ املرفــق‬\n      ‫بهــا القــرار الصــادر مــن فضيلــة القاضــي ‪...‬برقــم ‪34330734‬وتاريــخ‬\n      ‫‪1434/10/14‬هـ ـ اخلــاص بدعــوى املدعــي العــام ضــد املدعــى عليــه ‪...‬‬\n      ‫يف قضيــة حتــرش ومعاكســة وعلــى النحــو املوضــح يف القــرار واملتضمن‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــه وأوراق قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                         ‫علــى نبينــا محمــد و آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪129‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":122,"source_page_end":129,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6cf414dfe73b3f6370737c6e6525acc26c1add46f5848a5368553f2791257273","normalized_text_hash":"1d2dc0db9c0b97fa1a557779e7c3bf62577ed5c9132147885dbaadb6bd7965e8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p122-34330734"},{"id":"d541adb5-d063-5d7a-ab26-e76512b7e794","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترش -مضايقة امرأة -إقامة عالقة محرمة -اصطحاب امرأة - محاولة االعتداء على امرأة -حيازة مقاطع -التعزير بالسجن و اجللد -مصادرة اجلوال .","document_number":"34241950","case_number":"34150032","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/14","year":"1434","subject":"حترش -مضايقة امرأة -إقامة عالقة محرمة -اصطحاب امرأة - محاولة االعتداء على امرأة -حيازة مقاطع -التعزير بالسجن و اجللد -مصادرة اجلوال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34241950:‬تاريخه‪1434/06/14 :‬هـ‬\n    ‫رقم الدعوى‪ 34150032 :‬رقم قرار التصديق‬\n   ‫من محكمة االستئناف ‪ 34295385 :‬تاريخه‪:‬‬\n                            ‫‪1434/08/13‬هـ‬\n\n\n‫حتــرش ‪ -‬مضايقــة امــرأة ‪ -‬إقامــة عالقــة محرمــة ‪ -‬اصطحــاب امــرأة ‪-‬‬\n‫محاولــة االعتــداء علــى امــرأة ‪ -‬حيــازة مقاطــع ‪ -‬التعزيــر بالســجن و‬\n                                            ‫اجللــد ‪ -‬مصــادرة اجلــوال ‪.‬‬\n\n\n\n\n‫‪ .1‬مــا ذكــره أهــل العلــم مــن أن التعزيــر باملــال جائــز شــرع َا ‪ -‬وهــو‬\n‫مذهــب املالكيــة و احلنابلــة وهــو مــا اختــاره شــيخ اإلســام ابــن تيميــة‬\n                                                                ‫و ابــن القيــم ‪.‬‬\n                    ‫‪ .2‬قاعدة ( األصل أن اإلنسان مؤاخذ عما بحوزته ) ‪.‬‬\n‫‪ .3‬فتــوى الشــيخ محمــد بــن إبراهيــم ‪ -‬رحمــه اهلل ‪ -‬املتضمنــة أن عضــو‬\n    ‫هيئــة األمــر باملعــروف و النهــي عــن املنكــر ال يطلــب منــه مزكيــن ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه بإقامــة عالقــة محرمــة مــع املــرأة‬\n‫املشــتكية و اصطحابهــا و محاولــة االعتــداء عليهــا و حيــازة مقاطــع‬\n‫جنســية و تصويــر ذكــره ‪ ،‬و إرســال الصــور لعــدد مــن الفتيــات ‪ ،‬حيــث‬\n‫مت القبــض علــى املدعــى عليــه إثــر شــكوى مــن إحــدى النســاء بأنهــا‬\n‫تعرضــت العتــداء ومحاولــة اغتصــاب داخــل ســيارة املدعــى عليــه بعــد‬\n‫ركوبهــا معــه إليصالهــا ألحــد األماكــن ‪ ،‬فغيــر مســار الطريــق وحــاول‬\n\n                                                                                       ‫‪130‬‬\n\f      ‫اغتصابهــا واالعتــداء عليهــا بالســيارة حتــى أقنعتــه أنهــا ســتخرج مــرة‬\n      ‫أخــرى وأعطتــه رقــم جوالهــا فأخــذ يكثــر االتصــال عليهــا ‪ ،‬وواعدتــه‬\n      ‫باخلــروج ‪ ،‬فتــم القبــض عليــه ‪ ،‬وضبــط بحوزتــه جهــاز جــوال ‪ ،‬يحتــوي‬\n      ‫علــى مقاطــع جنســية وأرقــام نســاء وفتيــات بأســماء مســتعارة ‪ ،‬ووجــد‬\n      ‫أنــه يقــوم بإرســال صــورة قضيبــه الذكــري إلــى هــؤالء النســاء ‪،‬‬\n      ‫واتضــح أن املدعــى عليــه قــام باالعتــداء علــى املــرأة املشــتكية ومحاولــة‬\n      ‫اغتصابهــا ‪ ،‬كمــا دون محضــر محادثــة بــن املدعــى عليــه واملدعيــة ‪،‬‬\n      ‫وطلــب املدعــي العــام تعزيــر املدعــى عليــه بالســجن والغرامــة ومصــادرة‬\n      ‫جوالــه املســتخدم يف اجلرميــة وتطبيــق نظــام مكافحة اجلرائــم املعلوماتية‬\n      ‫‪ ،‬وتعزيــره لقــاء إقامــة عالقــة محرمــة مــع املــرأة ومحاولة االعتــداء عليها‬\n      ‫‪ ،‬أنكــر املدعــى عليــه مــا جــاء بدعــوى املدعــي العــام توجيــه التهمــة‬\n      ‫ـاء علــى مــا تقــدم حكمــت احملكمــة‬    ‫للمدعــى عليــه مبــا نســب إليــه وبنـ ً‬\n      ‫بتعزيــر املدعــى عليــه بالســجن ومصــادرة جوالــه املســتخدم يف اجلرميــة و‬\n      ‫إدخــال قيمتــه يف حســاب مؤسســة النقــد ‪ ،‬قــرر املدعــى عليــه واملدعــي‬\n      ‫وصــدق احلكــم مــن‬‫العــام اعتراضهمــا علــى احلكــم بالئحــة اعتراضيــة ُ‬\n                                                               ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34150032‬وتاريــخ‬\n      ‫‪ 1434/04/01‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34798078‬وتاريــخ‬\n      ‫‪1434/04/01‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/04/29‬ه ـ افتتحــت‬\n\n‫‪131‬‬\n\f‫اجللســة الســاعة ‪ 08 : 15‬وفيها حضر املدعي العام ‪ ...‬ســعودي اجلنســية‬\n‫ا‬ ‫املكلــف برقــم ه ـ م ‪ 6057 /1 /2 /‬يف ‪1433 / 1/1‬ه ـ وادعــى قائ ـ ً‬\n‫أدعــي علــى ‪ )........( :‬ســعودي اجلنســية مبوجــب الســجل رقــم (‪)........‬‬\n‫ـاء علــى محضــر رجــال الضبــط اجلنائــي بهيئة‬   ‫بتاريــخ ‪1434/2/24‬ه ـ وبنـ ً‬\n‫األمــر باملعــروف والنهــي عــن النكــر املتضمــن القبــض علــى املدعــى‬\n‫عليــه إثــر الشــكوى املقدمــة لهــم مــن قبــل امــرأة ترغــب الســتر علــى‬\n‫نفســها والتــي مفادهــا إنهــا تعرضــت العتــداء ومحاولــة اغتصــاب داخــل‬\n‫ســيارته نــوع‪ .........‬موديــل ‪ 2008‬لوحــة (‪ ).......‬أثنــاء ركوبهــا معه مشــوار‬\n‫مــن أمــام مكتــب الضمــان االجتماعــي إلــى ســوق املجــاز بالعزيزيــة إال‬\n‫إنهــا تفاجــأت بأنــه متجهــا علــى طريــق الشــرائع الطالــع للســيل طالب ـ ًا‬\n‫منهــا مرافقتــه إلــى منزلــه الكائــن بحــي الشــرائع إال إنهــا رفضــت‬\n‫وصرخــت فقــام مباشــرة بإيقــاف ســيارته علــى قارعــة الطريــق والنــزول‬\n‫منهــا وتأمــن األبــواب اخللفيــة مباشــرة وكان زجــاج الســيارة مظلــل‬\n‫متامــا ومــن ثــم ركــب باملقعــد األمامــي وقفــز معهــا باملقعــد اخللفــي وقــام‬\n‫باالعتــداء عليهــا محــاوال اغتصابهــا بالقــوة بعــد أن قــام بســحب جوالهــا‬\n‫منهــا عنــوة لكــي ال تســتنجد بأحــد مــع أنهــا قاومتــه وامتنعــت ودفعتــه‬\n‫بالقــوة ولكــن بــدون جــدوى وعندمــا رأتــه كاملســعور جلــأت ملسايســته‬\n‫واقناعــه بأنهــا ســتواعده وتخــرج معــه مــرة أخــرى ممــا جعلــه يقتنــع‬\n‫بذلــك بعدمــا حــاز علــى رقــم جوالهــا ومــن ثــم بــدأ يتصــل عليهــا بكثــرة‬\n‫ويراســلها ‪ ........‬مــن جوالــه رقــم(‪ )........‬وقــد حضــر املدعــى عليــه إلــى‬\n‫ســوق ‪ ........‬ليصطحــب املــرأة إلــى منزلــه ‪ ......‬ويكــرر فعلتــه ووجــد‬\n‫بحوزتــه جــوال نــوع ‪ .........‬رقمــه التسلســلي (‪ ).../...‬وبداخلــة شــريحة‬\n‫اتصــال‪ - .....‬ويحتــوي علــى أرقــام نســاء وفتيــات بأســماء مســتعارة يقــوم‬\n\n\n                                                                                       ‫‪132‬‬\n\f      ‫بإرســال قضيبــه الذكــري عليهــن ويحتــوي علــى مقاطــع وصــور جنســية‬\n      ‫وهــو اجلــوال الــذي اســتخدمه يف التواصــل مــع املــرأة املشــتكية (وقــد‬\n      ‫مت إعــداد محضــر مشــاهدة )بذلــك كمــا وجــد بحوزتــه جــوال اخــر‬\n      ‫وبداخلــة شــريحة اتصــال علمــا بأنــه اثنــاء ذلــك قــال (أعطونــي الســكني‬\n      ‫اللــي بالســيارة خلونــي اقتــل نفســي) ومت التحفــظ علــى الســكني نــوع‬\n      ‫‪.....‬وقــد اتضــح إنــه يســتغل العمــل علــى ســيارته بالذهــاب إلــى أماكــن‬\n      ‫بعيــدة ومــن ثــم يقــوم باالعتــداء عليهــن والتحــرش بهــن واغتصابهــن‪،‬‬\n      ‫واتضــح إن املدعــى عليــه قــام باالعتــداء علــى املــرأة املشــتكية ومحاولــة‬\n      ‫اغتصابهــا ودون محضــر ســماع محادثــة هاتفيــة بــن املدعــى عليــه‬\n      ‫واملــرأة املشــتكية ومفــاد االتصــال حتديــد موعــد املقابلــة بينهمــا‬\n      ‫واملــرأة تســأل املدعــى عليــه بقولهــا ( كيــف جــاء علــى بالــك تنــزل‬\n      ‫وتغلــق األبــواب شــكلك ســويت مــع غيــري) فقــال (مــدري كيــف جــات‬\n                            ‫علــى بالــي وأنــا خفــت انــك تفكــن البــاب وتنزلــن)‬\n      ‫وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بإقامــة عالقــة‬\n      ‫محرمــة مــع املــرأة املشــتكية واصطحابهــا ومحاولــة االعتــداء عليهــا‬\n      ‫وحيــازة مقاطــع جنســية وتصويــر ذكــره وإرســاله لعــدد مــن الفتيــات‬\n      ‫وحيــث إن مــا قــام بــه املدعــى عليــه فعــل محــرم ومجــرم ومعاقــب عليــه‬\n      ‫شــرعا ونظامـ ًا لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه باآلتــي ‪:‬‬\n      ‫‪ .1‬احلكــم عليــه بعقوبــة تعزيريــة لقــاء إقامــة عالقــة محرمــة مــع املــرأة‬\n                              ‫املشــتكية واصطحابهــا ومحاولــة االعتــداء عليهــا‬\n      ‫‪ .2‬الســجن والغرامــة وفقــا للفقــرة(‪ )1‬مــن املــادة السادســة مــن نظــام‬\n      ‫اجلرائــم املعلوماتيــة الصــادر باملرســوم امللكــي رقــم (م‪ )17/‬بتاريــخ‬\n              ‫‪1428/3/8‬ه ـ لقــاء انتــاج صــور مجرمــة وإرســالها عبــر اجلــوال‬\n\n\n‫‪133‬‬\n\f‫‪3‬ـ مصــادرة اجلــوال نــوع ‪ .........‬رقمــه التسلســلي(‪ ).../...‬املســتخدم يف‬\n‫اجلرميــة وفقــا للمــادة الثالثــة عشــر مــن ذات النظــام (علمــا بــأن احلــق‬\n‫اخلــاص انتهــى بالتنــازل) هــذه دعــواي وبســؤال املدعــى عليــه أنكــر مــا‬\n‫جــاء يف الدعــوى وقــال إن جوالــي اشــتريته مســتخدم وفيــه صــور قدميــة‬\n‫وأن املــرأة هــي التــي كانــت تراســله هكــذا أجــاب وبســؤاله ملــاذا لــم‬\n‫حتذفهــا قــال ال أعــرف لذلــك هكــذا أجــاب وبســؤال املدعــي العــام‬\n‫عــن البينــة فقــال أطلــب إمهالــي إلحضارهــا يــوم االثنــن ‪1434 /5 /6‬ه ـ‬\n‫الســاعة التاســعة صباح ـ ًا وأقفلــت اجللســة الســاعة التاســعة صباح ـ ًا‬\n‫ويف يــوم االثنــن املوافــق ‪ 1434/05/06‬ه ـ افتتحــت اجللســة الســاعة‬\n‫وفيهــا حضــر املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن‬\n‫البينــة فقــال لــم حتضــر وأطلــب إمهالــي إلحضارهــا يف يــوم االثنــن ‪20‬‬\n‫‪1434 /5 /‬ه ـ الســاعة التاســعة صباح ـ ًا وعليــه أقفلــت اجللســة الســاعة‬\n‫الثانيــة عشــر ظهــر ًا يف يــوم االثنــن املوافــق‪ 1434/05/20‬ه ـ افتتحــت‬\n‫اجللســة الســاعة (‪ )10.00‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه‬\n‫وجــرى ســؤال املدعــي العــام عــن بينتــه قــال لــم حتضــر وأطلــب إمهالــي‬\n‫عليــه رفعــت اجللســة إلــى يــوم االثنــن ‪1434/5/27‬ه ـ الســاعة التاســعة‬\n‫وأقفلــت اجللســة الســاعة (‪ )10.30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/20‬ه ـ ويف‬\n‫يــوم االثنــن املوافق‪1434/05/27‬ه ـ افتتحــت اجللســة الســاعة (‪)11.00‬‬\n‫وفيهــا حضــر املدعــي العــام واملدعــى عليــه وجــرى ســؤال املدعــي العــام‬\n‫عمــا طلــب االمهــال ألجلــه قــال حضــرت البينــة وأطلــب ســماعها وعليــه‬\n‫حضــر ‪ ...‬ســعودي ســجل رقــم ‪ ...‬وبســؤاله عمــا لديــه مــن شــهادة قــال‬\n‫أشــهد هلل تعالــى مبــا جــرى يف املكاملــة الهاتفيــة التــي متــت بــن املجنــي‬\n\n\n                                                                                     ‫‪134‬‬\n\f      ‫عليهــا واجلانــي يف مركــز الهيئــة واملتضمنــة (قــال فيــك نــروح البيــت‪.‬‬\n      ‫قالــت بــس مــا تكــون تســوي لــي زي ذاك اليــوم قــال ذاك اليــوم جانــي‬\n      ‫شــعاف‪ .‬قالــت وكنــت غيــر طبيعــي‪ .‬قــال يعنــي الســاعة كــم بكــرة‪.‬‬\n      ‫قالــت الســاعة ‪ 9‬صباحـاً‪ .‬قــال واهلل مــن جــد يــا قلبــي علــى طــول‪ .‬قالــت‬\n      ‫بــس كيــف جــاءت علــى بالــك تنــزل وتقفــل االبــواب شــكلك ســويت مــع‬\n      ‫غيــري‪ .‬قــال مــا دري كيــف جــاءت علــى بالــي وأنــا خفــت أنــك تفكــن‬\n      ‫البــاب وتنزلــن) أ‪.‬ه ـ هكــذا شــهد وبعــرض مــا جــاء يف شــهادة الشــاهد‬\n      ‫علــى املدعــى عليــه قــال مــا جــاء يف شــهادته غيــر صحيــح هكــذا أجــاب‬\n      ‫وبســؤال املدعــي العــام ألديــك مزيــد بينــة قــال نعــم وأطلــب إمهالــي‬\n      ‫إلحضارهــا وعليــه رفعــت اجللســة وأجلــت إلــى يــوم االثنــن ‪1434/6/5‬ه ـ‬\n      ‫الســاعة التاســعة وأقفلــت اجللســة الســاعة(‪ )11.30‬ويف يــوم االثنــن‬\n      ‫املوافــق‪ 1434/06/05‬ه ـ افتتحــت اجللســة الســاعة ‪ 11.00‬وفيهــا حضــر‬\n      ‫املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن البينــة فقــال لــم‬\n      ‫حتضــر وأطلــب إمهالــي إلحضارهــا يف يــوم الثالثــاء ‪1434 /6/13‬ه ـ‬\n      ‫الســاعة التاســعة صباح ـ ًا وعليــه أقفلــت اجللســة الســاعة احلاديــة عشــر‬\n                                                                     ‫والنصــف صباح ـ ًا ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/06/13‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 1.00‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه وبســؤال املدعــي العــام عمــا طلــب اإلمهــال ألجلــه قــال عدلــت‬\n      ‫عــن طلــب البينــة وأكتفــي مبــا جــاء يف أوراق املعاملــة وإجــراء الوجــه‬\n      ‫الشــرعي هكــذا أجــاب وعليــه جــرى االطــاع علــى أقوالــه صفحــة‬\n      ‫رقــم ‪ 14-13‬واملتضمنــة إقــراره بتصويــر ذكــره فبنــاء علــى مــا تقــدم‬\n      ‫وإلقــرار املدعــى عليــه بوجــود صــور ومقاطــع يف اجلــوال العائــد لــه‬\n\n\n‫‪135‬‬\n\f‫وألن مــا دفــع بــه ال يقبــل وألن األصــل أن اإلنســان مؤاخــذ عمــا بحوزتــه‬\n‫ولرجوعــه عــن أقوالــه يف تصويــر ذكــره ولعــدم البينــة علــى إرســال مــا‬\n‫ذكــر للغيــر وألن ذلــك موجــب التعزيــر وألن التعزيــر باملــال جائــز شــرع ًا‬\n‫وهــو مذهــب املالكيــة واحلنابلــة واختــاره شــيخ اإلســام ابــن تيميــة‬\n‫وابــن القيــم وإلنــكار املدعــى عليــه إقامــة العالقــة احملرمــة بامــرأة‬\n‫واصطحابهــا ومحاولــة االعتــداء عليهــا ولعــدم اكتمــال البينــة وألن‬\n‫شــهادة الشــاهد عضــو الهيئــة توجــب توجيــه الشــبهة وألن عضــو هيئــة‬\n‫األمــر باملعــروف والنهــي عــن املنكــر ال يطلــب منــه املزكيــن وألن‬\n‫هــذه فتــوى ســماحة الشــيخ محمــد بــن إبراهيــم رحمــه اهلل لذلــك كلــه‬\n‫فقــد ثبــت لــدى إدانــة املدعــى عليــه بحيازتــه لصــور ومقاطــع جنســية‬\n‫ولــم يثبــت إرســالها إلــى الغيــر وتوجــه الشــبهة بتصويــر ذكــره وقيامــه‬\n‫بعالقــة محرمــة مــع امــرأة أجنبيــة واصطحابهــا ومحاولــة االعتــداء‬\n‫عليهــا وعليــه فقــد حكمــت عليــه مبــا يلــي‪ -1 :‬صــرف النظــر عــن‬\n‫تطبيــق املــادة السادســة مــن نظــام اجلرائــم املعلوماتيــة ‪ -2‬بســجنه عشــرة‬\n‫أيــام لقــاء حيازتــه للصــور واملقاطــع وشــبهة تصويــر ذكــره ‪ -3‬بســجنه‬\n‫أربعــة أشــهر ابتــداء مــن تاريــخ إيقافــه و بجلــده مائتــي جلــده موزعــة علــى‬\n‫أربــع دفعــات بــن كل دفعــة وأخــرى أســبوع ًا لقــاء شــبهة قيامــه بعالقــة‬\n‫محرمــه مــع امــرأة أجنبيــه واصطحابهــا ومحاولــة االعتــداء عليهــا تنفــذ‬\n‫بعــد انتهــاء احملكوميــة الســابقة ‪ -4‬مصــادرة اجلــوال ذو ‪ ... /...‬وإدخــال‬\n‫قيمتــه يف حســاب مؤسســة النقــد العربــي الســعودي وبعــرض احلكــم‬\n‫علــى املدعــى عليــه قــرر اعتراضــه بالئحــة وجــرى تســليمه نســخه مــن‬\n‫القــرار الشــرعي وأفهــم بــأن لــه ثالثــن يوم ـ ًا مــن تاريــخ االســتالم وإذا‬\n‫مضــت املــدة ولــم يقــدم الالئحــة ســقط حقــه يف االعتــراض كمــا قــرر‬\n\n\n                                                                                       ‫‪136‬‬\n\f      ‫املدعــي العــام إعتراضــه بالئحــة وجــرى تســليمه نســخة مــن القــرار‬\n      ‫الشــرعي وأفهــم بنظــام االســتئناف وأقفلــت اجللســة الســاعة الواحــدة‬\n      ‫والنصــف ظهــر ًا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/13‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافق‪1434/09/08‬ه ـ‬\n      ‫افتتحــت اجللســة لــدى أنــا ‪ ...‬القاضــي باحملكمــة اجلزائيــة مبكــة‬\n      ‫املكرمــة والقائــم بعمــل فضيلــة القاضــي ‪ ...‬وفيهــا عــادت املعاملــة‬\n      ‫مــن محكمــة االســتئناف وبرفقهــا قرارهــا رقــم ‪ 34295385‬وتاريــخ‬\n      ‫‪1434/8/13‬ه ـ املتضمــن املوافقــة علــى احلكــم الصــادر مــن فضيلتــه‬\n      ‫برقــم ‪ 34241950‬وتاريــخ ‪1434/6/14‬ه ـ لــذا أمــرت باحلــاق ذلــك‬\n      ‫لضبطــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/08‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34938331‬وتاريــخ‬\n      ‫‪ 1434/8/1‬ه ـ املرفــق بهــا القــرار الشــرعي رقــم ‪ 34241950‬وتاريــخ‬\n      ‫‪ 1434/6/14‬ه ـ الصــادر مــن فضيلــة الشــيخ (‪ )........‬القاضــي يف‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام‬\n      ‫ضــد (‪ )........‬املتهــم بقضيــة حتــرش جنســي احملكــوم فيــه مبــا دون‬\n      ‫باطنــه‪ .‬وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا‬\n      ‫املوافقــة علــى احلكــم ‪ -‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                        ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪137‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":130,"source_page_end":137,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fd303bc8bb8072f4365296e6809dee7feb949789e6fb8a6a28f3633c1db2bb9e","normalized_text_hash":"c19d934cacde0bf0a5ce008101a0b73c7c741140f7f908899c9402bedd410ad3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p130-34241950"},{"id":"50fc6590-9e78-562d-9eff-057528357d53","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترش -مضايقة امرأة -حيازة جهاز جوال يحتوي على مقاطع جنسية -شهادة الشهود -توجه الشبهة -التعزير باجللد -مصادرة اجلوال -إتاف الصور -إبعاد عن الباد .","document_number":"34246414","case_number":"34159717","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبالحظة حيال مصادرة اجلوال و التوصية بإبعاد املدعى عليه إلى بالده","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/20","year":"1434","subject":"حترش -مضايقة امرأة -حيازة جهاز جوال يحتوي على مقاطع جنسية -شهادة الشهود -توجه الشبهة -التعزير باجللد -مصادرة اجلوال -إتاف الصور -إبعاد عن الباد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34246414 :‬تاريخه ‪1434/06/20 :‬هـ‬\n                    ‫رقم الدعوى ‪34159717 :‬‬\n               ‫رقم قرار التصديق من محكمة‬\n   ‫االستئناف‪ 34382558:‬تاريخه‪1434/12/19:‬هـ‬\n\n\n  ‫حتــرش ‪ -‬مضايقــة امــرأة ‪ -‬حيــازة جهــاز جــوال يحتــوي علــى مقاطــع‬\n  ‫جنســية ‪ -‬شــهادة الشــهود ‪ -‬توجه الشــبهة ‪ -‬التعزير باجللد ‪ -‬مصادرة‬\n                           ‫اجلــوال ‪ -‬إتــاف الصــور ‪ -‬إبعــاد عــن البــاد ‪.‬‬\n\n\n\n\n  ‫ال عبــرة باإلقــرار إال يف مجلــس القضــاء ‪ -‬كمــا يف نظــام املرافعــات‬\n                                            ‫الشــرعية املــادة رقــم (‪. )104‬‬\n\n\n\n\n  ‫ادعــى املدعــي العــام علــى املدعى عليه مبعاكســة النســاء و حيازة جوال‬\n  ‫يحتــوي علــى عــدد مــن املقاطــع اجلنســية ‪ ،‬حيــث إنــه مت القبــض عليــه‬\n  ‫مــن قبــل هيئــة األمــر باملعــروف والنهــي عــن املنكــر ‪ ،‬إثــر ورود بــاغ‬\n  ‫إليهــم مــن رجــال األمــن يف أحــد األســواق يتضمــن قيــام املدعــى عليــه‬\n  ‫مبضايقــة الفتيــات باملتاجــر ‪ ،‬ورمــي رقــم جوالــه ‪ ،‬فتــم القبــض عليــه ‪،‬‬\n  ‫وضبــط بحوزتــه جهــاز جــوال ‪ ،‬يحتــوي علــى ‪ 21‬مقطعـ ًا جنســي ًا وطلــب‬\n  ‫املدعــي العــام تعزيــر املدعــى عليــه لقــاء مــا نســب إليــه و مصــادرة اجلــوال‬\n  ‫وأنكــر املدعــى عليــه مــا جــاء بدعــوى املدعــي العــام ‪ ،‬طلــب مــن املدعــي‬\n  ‫العــام بينتــه علــى دعــواه ‪ ،‬فأحضــر للشــهادة عضــوي احلســبة وبســماع‬\n\n                                                                                          ‫‪138‬‬\n\f      ‫شــهادتهما شــهدا علــى إقــرار املدعــى عليــه برمــي القصاصــة الورقيــة و‬\n      ‫وجــد يف جوالــه عــدد مــن املقاطــع اجلنســية و بعرضهــا علــى املدعــى عليــه‬\n      ‫أنكرهــا ‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى‬\n      ‫عليــه باجللــد لقــاء توجــه الشــبهة بحقــه مبــا جــاء بدعــوى املدعــي العــام ‪،‬‬\n      ‫قنــع املدعــى عليــه باحلكــم و قــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n      ‫بالئحــة وعــادت املعاملــة مــن محكمــة االســتئناف مبالحظــة حيــال‬\n      ‫مصــادرة اجلــوال و التوصيــة بإبعــاد املدعــى عليــه إلــى بالده ‪،‬مت إســتجابة‬\n      ‫حاكــم القضيــة باحلكــم مبصــادرة جهــاز اجلــوال املوصــوف يف الدعــوى‬\n      ‫و إتــاف الصــور التــي بداخلــه و التوصيــة بإبعــاد املدعــى عليــه ‪ ،‬قنــع‬\n            ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬     ‫املدعــى عليــه باحلكــم ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم وتاريــخ ‪ 1434/04/07‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/04/07‬ه ـ ففــي يــوم الثالثــاء‬\n      ‫املوافــق‪ 1434/04/16‬ه ـ افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا‬\n      ‫ا‬‫حضــر ‪ ...‬بتعميــد مــن مرجعــه رقــم ه ـ م ‪ / 2/‬أ ‪ 342 /‬وأدعــى قائ ـ ً‬\n      ‫أدعــي علــى ‪ 25 ...‬عامـ ًا مينــي اجلنســية مبوجــب بطاقــة بديلــة رقــم‪ ...‬حيــث‬\n      ‫بتاريــخ ‪1434/3/17‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل هيئــة‬\n      ‫األمــر باملعــروف والنهــي عــن املنكــر إثــر ورود بــاغ إليهــم مــن رجــال‬\n      ‫أمــن متاجــر الســعودية بحــي يتضمــن قيــام املدعــى عليــه مبضايقــة‬\n      ‫الفتيــات باملتاجــر ورمــي رقــم جوالــه املــدون بقصاصــة ورقــة صغيــرة‬\n\n‫‪139‬‬\n\f‫عليهــن وقــد مت القبــض عليــه أثنــاء خروجــه مــن أســواق ( ‪ ، ) ...‬و ضبــط‬\n‫بحوزتــه جــوال نــوع بــاك ( ‪ ) ...‬ورقمــه التسلســلي ( ‪ ) ...‬اتضــح انــه‬\n‫يحتــوي علــى أكثــر مــن(‪ )21‬مقطــع جنســي خالــع‪ .‬وعنــد القبــض عليــه‬\n‫أفــاد بــأن اســمه ‪ ...‬مبوجــب بطاقــة مــزورة (فصلــت لهــا أوراق مســتقلة)‬\n‫بســماع أقــوال املدعــى عليــه اقــر برميــه قصاصــة ورقــة مســجل بهــا رقــم‬\n‫جوالــه علــى إحــدى النســاء وحيازتــه جلــوال يحتــوي علــى مقاطــع جنســية‬\n                                                                             ‫خالعــة‪.‬‬\n‫وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه مبعاكســة‬\n‫النســاء وحيــازة جــوال يحتــوي علــى عــدد مــن املقاطــع اجلنســية اخلالعــة‪.‬‬\n                                                 ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ -1‬إقراره املنوه عنه املدون على الصفحة رقم ( ‪ )5.4‬مبلف االســتدالل‬\n                                                            ‫املرفــق لفــة رقم ( ‪.)1‬‬\n‫‪ -2‬محضــر القبــض علــى املدعــى عليــه املنــوه عنــه املــدون علــى اللفــة‬\n                                                                           ‫رقم (‪.)5‬‬\n‫‪ -3‬محضــر املشــاهدة واالطــاع علــى جــوال املدعــى عليــه املنــوه عنــه‬\n                                                  ‫املــدون علــى اللفــة رقــم ( ‪.)4‬‬\n‫وحيــث إن مــا قــام بــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيــره رادعــة‬\n‫وتشــديدها عليــه وفــق برقيــة صاحــب الســمو امللكــي وزيــر الداخليــة‬\n‫رقــم (‪1‬ش ‪ )15/4268/‬وتاريــخ ‪1418/3/25‬هــ) ومبصــادرة جهــاز‬\n                               ‫جوالــه نــوع ( ‪ ) ...‬ورقمــه التسلســلي ( ‪. ) ...‬‬\n‫هكــذا أدعــى وبســؤال املدعــى عليــه عــن مــا جــاء بدعــوى املدعــي العــام‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه غيــر صحيــح جملــة‬        ‫أجــاب قائ ـ ً‬\n\n\n                                                                                        ‫‪140‬‬\n\f      ‫ا‬\n      ‫ا هكــذا أجــاب وبســؤال املدعــي العــام عــن بينتــه أجــاب قائـ ُ‬     ‫وتفصيـ ً‬\n      ‫نعــم لــدي وأطلــب إمهالــي إلحضارهــا فأمهــل وحددت جلســة يــوم اإلثنني‬\n      ‫املوافــق ‪1434 / 4 / 22‬ه ـ ‪ ....‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/16‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة املســاعد برقــم ‪ ....‬وتاريــخ‬\n      ‫‪ 1434/04/07‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34850883‬وتاريــخ‬\n      ‫‪ 1434/04/07‬ه ـ ففــي يــوم األحــد املوافــق ‪ 1434/06/18‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة وفيهــا حضــر املدعــي العــام ‪ ....‬وبســؤاله عــن البينــة التــي‬\n      ‫ا نعــم وأحضــر للشــهادة كل مــن ‪... -1‬‬          ‫وعــد بإحضارهــا أجــاب قائ ـ ً‬\n      ‫‪ ... -2‬وبســؤالهما عــن شــهادتهما أفــاد الشــاهد األول حيــث أنــي أحــد‬\n      ‫رجــال األمــر باملعــروف والنهــي عــن املنكــر وردتنــا أن شــاب ًا قــام برمــي‬\n      ‫رقــم جوالــه علــى إحــدى الفتيــات وعنــد تواجــدي وجــدت الرقــم ملقــى‬\n      ‫علــى األرض وقــام املدعــى عليــه باالعتــراف أمامــي وبتصفــح جوالــه‬\n      ‫وجــدت بداخلــه قرابــة واحــد وعشــرون مقطعــا جنســي ًا هكــذا أفــاد‬\n      ‫الشــاهد األول ‪ ...‬وبســؤال الشــاهد الثانــي ‪ ...‬أفــاد مبثــل مبــا أفــاد بــه‬\n      ‫الشــاهد األول هكــذا شــهدا وعليــه رفعــت اجللســة ‪ ..‬وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                      ‫‪ 1434/06/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة املســاعد برقــم وتاريــخ‬\n\n\n‫‪141‬‬\n\f‫‪ 1434/04/07‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪1434/04/07‬‬\n‫ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/06/19‬ه ـ افتتحــت اجللســة الســاعة‬\n‫وفيهــا حضــر املدعــي العــام ‪ ...‬واملدعــى عليــه وجــرى اســتجواب املدعــى‬\n‫ا غيــر صحيــح وأنــي لــم أعتــرف‬  ‫عليــه وبعــرض الشــهادة عليــه أجــاب قائـ ً‬\n‫أمــام الهيئــة واجلــوال الــذي ضبــط بحوزتــي قــد اشــتريته قريبـ ًا وال أعرف‬\n‫مــا بداخلــه وبتأمــل أوراق املعاملــة وبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وإلنــكار املدعــى عليــه وملــا جــاء يف شــهادة الشــهود املعدلــة‬\n‫شــرع ًا ولكونهــا غيــر موصلــة فلــم يشــاهد املدعــى عليــه وهــو يقــوم‬\n‫باجلنايــة وألن مــا دفــع بــه املدعــى عليــه ال يقــوى علــى رد التهمــة ال ســيما‬\n‫مــع إقــراره عنــد رجــال احلســبة وألنــه ال عبــرة باإلقــرار إال يف مجلــس‬\n‫القضــاء كمــا يف نظــام املرافعــات املــادة ‪ 104‬وعليــه فقــد تقــرر لــدي‬\n‫مــا يلــي توجهــت الشــبهة‪ .‬علــى املدعــى عليــه مبــا نســب إليــه وحكمــت‬\n‫بتعزيــره باجللــد ســبعني جلــدة دفعــة واحــدة ومبــا تقــدم حكمــت وبعــرض‬\n‫احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر املدعــى عليــه القناعــة‬\n‫باحلكــم وأمــا املدعــي العــام فقــرر االعتــراض بالئحــة‪ ...‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪ 1434/06/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫الرئيــس املســاعد باحملكمــة اجلزائيــة مبكــة املكرمــة برقــم وتاريــخ‬\n‫‪ 1434/04/07‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪1434/04/07‬ه ـ‬\n‫ففــي يــوم األحــد املوافــق ‪ 1434/11/09‬ه ـ افتتحــت اجللســة الســاعة‬\n‫وفيهــا عــادت أوراق املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n\n\n                                                                                        ‫‪142‬‬\n\f      ‫وبرفقهــا قرارهــا رقــم وتاريــخ ‪1434 / 9 / 21‬ه ـ الصــادر مــن الدائــرة‬\n      ‫اجلزائيــة األولــى واملتضمــن مــا نصــه بعــد املقدمــة (وبدراســة احلكــم‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا إعادتهــا لفضيلــة حاكــم‬\n      ‫القضيــة ملالحظــة أو ًال املدعــي العــام طالــب مبصــادرة الهاتــف اجلــوال‬\n      ‫وعلــى فضيلتــه احلكــم مبصادرتــه الحتوائــه علــى مقاطــع جنســية خليعــة‬\n      ‫وإتــاف الصــور التــي بــه حتــى لــو أدى إلــى إتالفــه ثانيـ ًا علــى فضيلتــه أن‬\n      ‫يوصــي بإبعــاد املدعــى عليــه اتقــاء لشــره واهلل املوفــق وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ) انتهــى نــص القــرار وهــو مذيــل‬\n      ‫بأختــام وتواقيــع أصحــاب الفضيلــة رئيــس وعضــوي الدائــرة املذكــورة‬\n      ‫ولوجاهــة مــا ذكــره أصحــاب الفضيلــة فقــد حكمــت إضافــة إلــى مــا‬\n      ‫ســبق مصــادرة الهاتــف اجلــوال املوصــوف يف الدعــوى وإتــاف الصــور‬\n      ‫ـاء لشــره وبعرضــه علــى‬  ‫التــي بداخلــه وأوصــي بإبعــاده مــن البــاد اتقـ ً‬\n      ‫املدعــى عليــه قــرر القناعــة فأمــرت بإحلــاق ذلــك يف الضبــط والقــرار‬\n      ‫وإرســال كامــل أوراق املعاملــة إلــى محكمــة االســتئناف مبكــة‬\n      ‫املكرمــة لعــرض مــا أجرينــاه علــى أصحــاب الفضيلــة رئيــس وعضــوي‬\n      ‫الدائــرة املذكــورة وفــق اهلل اجلميــع ملــا يحبــه ويرضــاه ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/09‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة املســاعد مبكــة املكرمــة برقــم‬\n      ‫وتاريــخ ‪ 1434/11/25‬ه ـ املرفــق بهــا القــرار القضائــي رقــم وتاريــخ‬\n      ‫‪ 1434/6/20‬ه ـ الصــادر مــن فضيلــة الشــيخ (‪ )........‬القاضــي يف‬\n\n\n‫‪143‬‬\n\f‫احملكمــة اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام‬\n‫ضــد ‪ ... /‬مينــي اجلنســية املتهــم بقضيــة مضايقــة الفتيــات ورمــي رقــم‬\n‫جوالــه املــدون بقصاصــة ورقــة صغيــرة عليهــن احملكــوم فيــه مبــا دون‬\n                                                                      ‫باطنــه‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا املوافقــة‬\n‫علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى‬\n                                   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪144‬‬\n\f145\n\f146\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":138,"source_page_end":146,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2c66a793802753edc69df663736c5e71cf6c1a3012ff7eb35d16a3af9cf69036","normalized_text_hash":"81d4686e26908ceb66b625c1fb7d3777bc1c06d57899a066a2fe3a6ceb8e1413","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p138-34246414"},{"id":"a40e46b8-a810-50b6-93ae-cd4789fc95b6","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -املطالبة بإقامة حد القذف -عدم املؤاخذة على األقوال يف مجلس احلكم -اتهام الزوجة لزوجها -اتهام املدعى عليها للمدعي على وجه الشكاية لدى المحكمة -تلفظ أحد اخلصمن على صاحبه حال الشكاية فإنه يتحمل منه ذلك -احلكم برد دعوى املدعي وإخاء سبيل املدعى عليها.","document_number":"33269759","case_number":"33153583","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/26","year":"1434","subject":"زوجية -املطالبة بإقامة حد القذف -عدم املؤاخذة على األقوال يف مجلس احلكم -اتهام الزوجة لزوجها -اتهام املدعى عليها للمدعي على وجه الشكاية لدى المحكمة -تلفظ أحد اخلصمن على صاحبه حال الشكاية فإنه يتحمل منه ذلك -احلكم برد دعوى املدعي وإخاء سبيل املدعى عليها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/26 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33269759 :‬‬\n                         ‫َر ْق ُم الدعوى‪33153583 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34205252‬تاريخه‪1434/5/4 :‬هـ‬\n\n\n      ‫زوجيــة ‪ -‬املطالبــة بإقامــة حــد القــذف ‪ -‬عــدم املؤاخــذة علــى األقــوال‬\n      ‫يف مجلــس احلكــم ‪ -‬اتهــام الزوجــة لزوجهــا ‪ -‬اتهــام املدعــى عليهــا‬\n      ‫للمدعــي علــى وجــه الشــكاية لــدى احملكمــة ‪ -‬تلفــظ أحــد اخلصمــن‬\n      ‫علــى صاحبــه حــال الشــكاية فإنــه يتحمــل منــه ذلــك ‪ -‬احلكــم بــرد‬\n                                 ‫دعــوى املدعــي وإخــاء ســبيل املدعــى عليهــا‪.‬‬\n\n\n\n\n       ‫‪ -‬قوله تعالى ‪ ( :‬ال يحب اهلل اجلهر بالسوء من القول إال من ظلم)‪.‬‬\n      ‫‪ -‬حديــث اختصــام احلضرمــي والكنــدي الــذي أخرجــه مســلم يف‬\n      ‫صحيحــه ( ‪ ) 86/1‬والــذي قــال فيــه احلضرمــي (إن الرجــل ال يبالــي‬\n                                   ‫علــى مــا حلــف وليــس يتــورع عــن شــيء )‪.‬‬\n      ‫‪ -‬قــال النــووي يف شــرحه علــى صحيــح مســلم ( ‪ ( :) 162/2‬وفيــه أن‬\n      ‫أحــد اخلصمــن إذا قــال لصاحبــه إنــه ظالــم أو فاجــر أو نحــوه يف حــال‬\n                                                ‫اخلصومــة يحتمــل ذلــك منــه )‪.‬‬\n\n\n\n      ‫ادعــى املدعــي علــى املدعــى عليهــا واملعــرف بهــا مــن قبــل والدهــا أن‬\n      ‫املدعــى عليهــا قــد تقدمــت بشــكوى ضــده لــدى احملكمــة تتهمــه بأنــه‬\n      ‫ال يصلــي ‪ ،‬ال يف البيــت وال يف اجلماعــة ‪ ،‬كمــا ادعــت أنــه ميــارس أعمال‬\n\n‫‪147‬‬\n\f‫مشــينة معهــا ومــع غيرهــا واتهمتــه بتعاطــي املخــدرات وأنــه قــام بضربهــا‬\n‫وإهانتهــا وحيــث إن هــذه األمــور ال صحــة لهــا طلــب تأديبهــا وإقامــة حــد‬\n‫القــذف عليهــا ‪ -‬وبســؤال املدعــى عليهــا عــن دعــوى املدعــي صادقــت‬\n‫علــى مــا ذكــره املدعــي وأنهــا اتهمتــه يف الشــكوى املقدمــة منهــا لــدى‬\n‫احملكمــة العامــة وكان ذلــك لــدى احملكمــة فقــط ولــم تتكلــم بــه‬\n‫خــارج احملكمــة ‪ -‬بعــرض ذلــك علــى املدعــي صــادق علــى ذلــك وأن‬\n‫ذلــك كان يف احملكمــة العامــة إال أنــه انتشــر بســبب أوراق التبليــغ لدى‬\n‫أقــارب املدعــي ‪ -‬صــادق الطرفــان علــى أن اتهــام املدعــى عليهــا للمدعــي‬\n‫كان علــى وجــه الشــكاية لــدى احملكمــة العامــة ‪ -‬صــدر احلكــم بــرد‬\n‫دعــوى املدعــي ضــد املدعــى عليهــا وإخــاء ســبيل املدعــى عليهــا ‪ -‬قــرر‬\n‫املدعــي اعتراضــه علــى احلكــم بالئحــة اعتراضيــة‪ -‬صــدق احلكــم مــن‬\n                                                         ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل و حــده وبعــد إنــه يف يــوم الثالثــاء ‪1433/3/15‬ه ـ لــدي أنــا ‪...‬‬\n‫القاضــي باحملكمــة اجلزئيــة بالريــاض فتحــت اجللســة الســاعة الثامنــة‬\n‫للنظــر يف القضيــة املقيــدة بهــذه احملكمــة برقــم ‪ 33404441‬و تاريــخ‬\n‫‪1433/03/01‬ه ـ و احملالــة إلــي مــن فضيلــة الرئيــس برقــم ‪33153583‬‬\n‫ولــم يحضــر املدعــي و ال املدعــى عليــه و ال مــن ينــوب عنهمــا ولــم‬\n‫يتقدمــا بعــذر تقبلــه احملكمــة لــذا فقــد جــرى شــطب القضيــة للمــرة‬\n‫األولــى اســتناد ًا للمــادة الثالثــة واخلمســن مــن نظــام املرافعــات وختمــت‬\n‫اجللســة الســاعة الثامنــة والنصــف وحــرر يف ‪1433/3/15‬ه ـ ثــم إنــه يف‬\n\n                                                                                    ‫‪148‬‬\n\f      ‫يــوم الســبت ‪1433/5/15‬ه ـ فتحــت اجللســة الســاعة العاشــرة والنصــف‬\n      ‫صباح ـ ًا وفيهــا ‪...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬وادعــى علــى‬\n      ‫املــرأة احلاضــرة معــه ‪...‬ســعودية مبوجــب الســجل املدنــي رقــم ‪...‬املعــرف‬\n      ‫ا يف‬ ‫بهــا مــن قبــل والدهــا ‪...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬قائـ ً‬\n      ‫دعــواه ســبق أن تقدمــت املدعــى عليهــا هــذه احلاضــرة بشــكوى ضــدي‬\n      ‫لــدى احملكمــة العامــة بالريــاض تتهمنــي بأننــي ال أصلــي أبــد ًا ال يف‬\n      ‫البيــت وال مــع اجلماعــة كمــا ادعــت أننــي أمــارس الشــذوذ اجلنســي‬\n      ‫واللــواط معهــا ومــع غيرهــا واتهمتنــي بتعاطــي املخــدرات وأننــي قمــت‬\n      ‫بضربهــا و إهانتهــا وحيــث إن هــذه األمــور ال صحــة لهــا لــذا أطلــب‬\n      ‫تأديبهــا وإقامــة حــد القــذف عليهــا هــذه دعــواي وبســؤال املدعــى عليهــا‬\n      ‫عــن دعــوى املدعــي أجابــت قائلــة مــا ذكــره املدعــي مــن أننــي اتهمتــه‬\n      ‫مبــا ذكــره يف دعــواه يف شــكواي املقدمــة ضــده لــدى احملكمــة العامــة‬\n      ‫بالريــاض هــذا صحيــح إال أن ذلــك كان لــدى احملكمــة فقــط ولــم‬\n      ‫أتكلــم بذلــك خــارج احملكمــة هــذا جوابــي وبعــرض ذلــك علــى املدعــي‬\n      ‫قال صحيح أن املدعى عليها قد تكلمت بهذا الكالم لدى احملكمة‬\n      ‫العامــة فقــط إال أن هــذا األمــر قــد انتشــر بســبب أوراق التبليــغ لــدى‬\n      ‫أقاربــي هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n      ‫صــادق الطرفــان علــى أن اتهــام املدعــى عليهــا للمدعــي كان علــى وجــه‬\n      ‫الشــكاية لــدى احملكمــة العامــة ونظــر ًا لكــون مثــل هــذا االتهــام ممــا‬\n      ‫قــد يخفــى علــى غيــر الزوجــن يف عالقتهــا الزوجيــة وقــد خــرج على وجه‬\n      ‫الدعــوى ولقولــه تعالــى ( ال يحــب اهلل اجلهــر بالســوء مــن القــول إال مــن‬\n      ‫ظلــم ) و حديــث اختصــام احلضرمــي والكنــدي الــذي أخرجــه مســلم‬\n      ‫يف صحيحــه (‪ )86/1‬والــذي قــال فيــه احلضرمــي (( إن الرجــل فاجــر‬\n\n\n‫‪149‬‬\n\f‫ال يبالــي علــى مــا حلــف عليــه وليــس يتــورع عــن شــيء)) قــال النــووي يف‬\n‫شــرحه علــى صحيــح مســلم (‪ ( : )162/2‬وفيــه أن أحــد اخلصمــن إذا‬\n‫قــال لصاحبــه إنــه ظالــم أو فاجــر أو ن ــحوه يف حــال اخلصومــة يحتمل ذلك‬\n‫منــه )) لذلــك كلــه فقــد حكمــت بــرد دعــوى املدعــي جتــاه املدعــى‬\n‫عليهــا وأخليــت ســبيل املدعــى عليهــا منهــا وبإعــان احلكــم لــم يقنــع‬\n‫بــه املدعــي وطلــب رفــع احلكــم حملكمــة االســتئناف واســتعد بتقــدمي‬\n‫الئحــة اعتــراض فأفهــم باملراجعــة بعــد عشــرة أيــام الســتالم نســخة مــن‬\n‫احلكــم و أن عليــه تقــدمي اعتراضــه خــال ثالثــن يومـ ًا مــن املوعــد املقرر‬\n‫الســتالم نســخة احلكــم وختمــت اجللســة الســاعة احلاديــة عشــرة وحــرر‬\n‫يف ‪1433/5/15‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه‪.‬‬\n‫احلمــد هلل وحــده أطلــع قضــاة الدائــرة اجلزائيــة األولــى علــى املعاملــة‬\n‫الــواردة مــن احملكمــة اجلزائيــة بالريــاض واملرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة القاضــي‪ ..... /‬برقــم ‪ 33269759‬وتاريــخ ‪1433/5/26‬ه ـ‬\n‫واخلــاص بدعــوى ‪ ....‬ضــد‪ .... /‬وموضوعهــا دعــوى كيديــه وبعد التدقيق‬\n‫تقــرر املصادقــة علــى احلكــم لعــدم موجــب املالحظــة وصلــى اهلل علــى‬\n                                                    ‫نبينــا محمــد واهلل املوفــق ‪.‬‬\n\n\n\n\n                                                                                      ‫‪150‬‬\n\f151\n\f152\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":147,"source_page_end":152,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0e41849d66fdcc2e91ee3a61605995d63039bb99f3c538c42441e4423e972ef6","normalized_text_hash":"e13d0b7c5025504a4eec46f17d8175e84ea8dd971403f4f9588eef4ac05b5301","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p147-33269759"},{"id":"c79114ad-0973-5e17-b222-28e3e4da3f31","document_type":"judgment","category":"judicial","subcategory":"general","title":"سب وقذف -سب وقذف أئمة املساجد -إنكار املدعى عليه -رد دعوى املدعي العام لعدم وجود بينة -إخاء سبيل املدعى عليه .","document_number":"34176751","case_number":"34100434","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/02","year":"1434","subject":"سب وقذف -سب وقذف أئمة املساجد -إنكار املدعى عليه -رد دعوى املدعي العام لعدم وجود بينة -إخاء سبيل املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34176751:‬تاريخه ‪1434/04/02:‬هـ‬\n                        ‫رقم الدعوى ‪34100434:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‬\n               ‫‪ 34213534:‬تاريخه‪1434/05/15:‬هـ‬\n\n\n      ‫ســب وقــذف ‪ -‬ســب وقــذف أئمــة املســاجد ‪ -‬إنــكار املدعــى عليــه ‪ -‬رد‬\n      ‫دعــوى املدعــي العــام لعــدم وجــود بينــة ‪ -‬إخــاء ســبيل املدعــى عليــه ‪.‬‬\n\n\n\n\n                                  ‫‪ -‬املادة الثالثة من نظام اإلجراءات اجلزائية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بالتطــاول علــى أئمــة املســاجد‬\n      ‫ووصفهــم بالــكالب التــي تنبــح وهــم يقــرؤون القــرآن وقــت الصــاة ‪،‬‬\n      ‫قبــض علــى املدعــى عليــه علــى إثــر بــاغ مــن أحــد األشــخاص ‪ ،‬قصــده‬\n      ‫املدعــى عليــه ‪ ،‬وســأله متــى تفتــح احملــات ؟ ‪ .‬فــرد عليــه (بعــد قليــل)‬\n      ‫‪ ،‬فقــال ‪( :‬إذا خلصــت هالــكالب التــي تنبــح ويقصــد أئمــة املســاجد‬\n      ‫‪ ،‬وهــم يقــرؤون القــرآن أثنــاء الصــاة ‪ ،‬وكررهــا ثالث ـ ًا ‪ ،‬وطلــب‬\n      ‫تعزيــره لقــاء ذلــك ‪ ،‬أنكــر املدعــى عليــه مــا جــاء بدعــوى املدعــي العــام‬\n      ‫‪ ،‬طلــب مــن املدعــي العــام بينتــه علــى دعــواه فقــرر انــه ليــس لديــه إال‬\n      ‫مــا جــاء يف أوراق املعاملــة وقــد طلــب املبلــغ عــدة مــرات ولــم يحضــر‪،‬‬\n      ‫احلكــم بــرد دعــوى املدعــي العــام ضــد املدعــى عليــه لعــدم ثبــوت قيــام‬\n      ‫املوجــب الشــرعي ‪ ،‬وإخــاء ســبيله يف هــذه القضيــة ‪ ،‬قــرر املدعــي العام‬\n      ‫اعتراضــه علــى احلكــم مكتفيـ ًا مبــا قدمــه يف الئحــة الدعــوى ‪ ،‬صــدق‬\n                                                 ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n‫‪153‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزئيــة‬\n‫مبحافظــة القطيــف بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزئيــة مبحافظــة القطيــف برقــم وتاريــخ ‪1434/3/1‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم وتاريــخ ‪1434/3/1‬ه ـ ففــي يــوم األحــد‬\n‫‪ 1434/03/15‬ه ـ افتتحــت اجللســة األولــى الســاعة ‪ 09 :30‬وفيهــا‬\n‫حضــر املدعــي العــام بصفتــي مدعيـ ًا عامــا يف دائــرة التحقيــق واالدعــاء‬\n‫العــام مبحافظــة القطيــف أدعــي البالــغ مــن العمــر (‪ )35‬عام ـ ًا ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬غيــر محصــن موظــف‬\n‫حكومــي قبــض عليــه بتاريــخ ‪1433/12/9‬ه ـ وأفــرج عنــه بتاريــخ‬\n‫‪1433/12/11‬ه ـ اســتناد ًا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‬\n‫ومقــر إقامتــه محافظــة القطيــف حيــث انــه باالطــاع علــى محضر تنفيذ‬\n‫املهمــة املعــد مــن قبــل رجــال الضبــط اجلنائــي بالدوريــات األمنيــة بالدمــام‬\n‫وكامــل أوراق القضيــة تبــن انــه قبــض علــى املدعــى عليــه بحــي بشــارع‬\n‫بتاريــخ ‪1433/12/9‬ه ـ اثــر بــاغ مــن احــد املقيمــن عــن قيــام املدعــى‬\n‫عليــه بســب الديــن وبضبــط إفــادة املبلــغ‪( /‬فلســطيني اجلنســية) أفــاد أنــه‬\n‫كان موجــود بشــارع خلــف شــركة وكان وقــت صــاة املغــرب وحضــر‬\n‫املدعــى عليــه وســأله متــى تفتــح احملــات فــرد عليــه بعــد شــوي فقــال‬\n‫يعنــي إذا خلصــت هالــكالب اللــي تنبــح ويقصــد أئمــة املســاجد وهــم‬\n‫يقــرؤون القــرآن وقــت الصــاة وكررهــا ثــاث مــرات ولــم يــرد عليــه‬\n‫ومــن ثــم اتصــل علــى الدوريــات وقبضــوا عليــه مضيف ـ ًا بأنــه ال يعرفــه‬\n‫مــن قبــل وقــد أســفر التحقيــق عــن اتهامــه بالتطــاول علــى أئمــة املســاجد‬\n\n                                                                                       ‫‪154‬‬\n\f      ‫ووصفهــم بالــكالب التــي تنبــح وهــم يقــرؤون القــرآن وقــت الصــاة‬\n                                                     ‫وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n                    ‫‪ -1‬محضر تنفيذ املهمة املنوه عنه املرفق على اللفة رقم(‪)3‬‬\n      ‫‪ -2‬مــا ورد بشــهادة املبلــغ املدونــة علــى الصفحتــن (‪1‬و‪)9‬مــن ملــف تقرير‬\n                                                                ‫األحــوال األمنيــة املوحد‬\n      ‫‪-3‬إقــراره بأنــه ال يعــرف املبلــغ مــن قبــل وكذلــك املبلــغ بأنــه ال يعــرف‬\n      ‫املتهــم وال يوجــد بينهمــا أي عــداوة وكونهمــا يشــاهدان بعضهمــا‬\n      ‫ألول مــرة ويتقابــان وقــت صــاة املغــرب يؤيــد صحــة مــا ذكــره املبلــغ‬\n      ‫وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة وحيــث‬\n      ‫إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرع ًا لــذا اطلــب إثبــات مــا أســند إليــه واحلكــم‬\n      ‫عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره هــذه دعواي والســام وبعرض‬\n      ‫ذلــك علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام ضــدي مــن القبض‬\n      ‫علــي يف تاريــخ ‪1433/12/9‬ه ـ يف شــارع امللــك ‪ ...‬خلــف شــركة بالدمام‬\n      ‫وقــت صــاة املغــرب صحيــح أمــا مــا ذكــره مــن ســبي للديــن بالعبــارة‬\n      ‫التــي ذكــر غيــر صحيحــة جملــة وتفصيــا والصحيــح أننــي شــاهدت‬\n      ‫عامــا يف محــل يعمــل فســألته متــى يفتــح احملــل الــذي بجــواره فقــال‬\n      ‫بعــد قليــل ثــم انصرفــت عنــه ولــم يحصــل بينــي وبينــه أي نقــاش او كالم‬\n      ‫زائــدا علــى مــا ذكرتــه وبطلــب البينــة مــن املدعــي العــام قــال بينتــي‬\n      ‫محضــر تنفيــذ املهمــة املرفــق لفــة رقــم (‪ )3‬ومبطالتــه وجدتــه يتضمــن‬\n      ‫مــا نصــه ( أثنــاء اســتالمنا يف هــذا اليــوم وردنــا مــن العمليــات عــن مبلــغ‬\n      ‫يفيــد بوجــود شــخص يتلفــظ علــى الديــن بألفــاظ ســيئة مت التحفــظ‬\n      ‫عليــه وتســليمه لشــرطة شــمال الدمــام وأيضــا شــهادة املبلــغ املدونــة علــى‬\n\n\n‫‪155‬‬\n\f‫صفحــة رقــم (‪ )1‬و (‪ )9‬مــن ملــف التحقيــق املرفــق ومبطالعتهــا وجدتهــا‬\n‫تتضمــن إفــادة املقيــم وعمــره (‪ )24‬عامـ ًا فلســطيني اجلنســية (أنــه شــاهد‬\n‫شــخصا خلــف إشــارة شــركة وقــت صــاة املغــرب ســعودي اجلنســية‬\n‫ويرتــدي ثوبــا أبيضــا وســأله متــى يفتــح احملــل قلــت بعــد شــوي وقــال‬\n‫لــي يعنــي إذا خلصــت الــكالب اللــي تنبح‪...‬إلــخ ) وبعــرض ذلــك علــى‬\n‫املدعــى عليــه قــال مــا ذكــر يف محضــر الدوريــات مــن القبــض علـ ّـي‬\n‫وقــت الواقعــة صحيــح وأمــا مــا ذكــر مــن ســبي للديــن وإفــادة الشــخص‬\n‫ا وأنــا أدرك‬  ‫الــذي قــام بتقــدمي البــاغ غيــر صحيــح جملــة وتفصي ـ ً‬\n‫خطــورة هــذا الــكالم أو التعــرض للديــن بســخرية أو اســتهزاء أو ســب‬\n‫وأطلــب إحضــار هــذا الشــخص لســماع مــا لديــه ونظــرا ألهميــة القضيــة‬\n‫وتوقفهــا علــى إفــادة املبلــغ فقــد أمــرت برفــع اجللســة إلحضــار الشــخص‬\n‫الــذي قــام بتقــدمي البــاغ لســماع مــا لديــه بعــد إعــام الطرفــن باحلضــور‬\n‫يــوم األحــد ‪1434/3/22‬ه ـ الســاعة العاشــرة والنصــف صباحــا لــذا‬\n‫رفعــت اجللســة يف متــام الســاعة العاشــرة صباحــا وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى الــه وصحبــه وســلم ويف يــوم األحــد ‪ 1434/03/22‬ه ـ‬\n‫افتتحــت اجللســة الثانيــة الســاعة العاشــرة صباحـ ًا وفيهــا حضــر املدعــي‬\n‫العــام واملدعــى عليــه ولــم يحضــر الشــاهد املذكــور مــع طلبــه عــن طريــق‬\n‫محضــر اخلصــوم مبوجــب خطابــه املرفــق والــذي يتضمــن أن رقــم هاتفــه‬\n‫مغلــق مــع تكــرار االتصــال عليــه أكثــر مــن مــره وقــال املدعــي العــام‬\n‫إننــي اطلــب مهلــة إلحضــار الشــاهد املذكــور يف اجللســة القادمــة لــذا‬\n‫أفهمتــه بــأن هــذه هــي املهلــة األخيــرة إلحضــار شــاهده وإن لــم يحضــره‬\n‫ســيتم البــت يف القضيــة يف اجللســة القادمــة لــذا رفعــت اجللســة بعــد‬\n‫إعــام الطرفــن باحلضــور يــوم االحــد ‪1434/3/29‬ه ـ الســاعة العاشــرة‬\n\n\n                                                                                    ‫‪156‬‬\n\f      ‫والنصــف صباح ـ ًا وعليــه جــرى التوقيــع أغلقــت اجللســة يف متــام الســاعة‬\n      ‫العاشــرة وخمســة عشــر دقيقــة وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبه وســلم ويف يوم األحد ‪ 1434/03/29‬هـ افتتحت اجللســة األولى‬\n      ‫الســاعة الثامنــة صباح ـ ًا وفيهــا حضــر الطرفــان وبســؤال املدعــي العــام‬\n      ‫عــن الشــاهد املذكــور قــال قــد مت االتصــال عليــه عــدة مــرات وجوالــه‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى‬ ‫مغلــق ولــم نســتطع الوصــول إليــه فبنـ ً‬\n      ‫واإلجابــة وإلــى إنــكار املدعــى عليــه دعــوى املدعــي العــام ولــم يثبــت‬\n      ‫دعــواه وإلــى مــا تــدل عليــه املــادة الثالثــة مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫مــن عــدم جــواز توقيــع عقوبــة جزائيــة علــى أي شــخص إال علــى أمــر‬\n      ‫محظــور ومعاقــب عليــه شــرع ًا أو نظامـ ًا وبعــد ثبــوت اإلدانــة وذلــك غيــر‬\n      ‫متوفــر يف هــذه القضيــة لــكل مــا ســبق فقــد رددت دعــوى املدعــي العــام‬\n      ‫ضــد املدعــى عليــه لعــدم ثبــوت قيــام املوجــب الشــرعي وأخليــت ســبيله‬\n      ‫مــن هــذه القضيــة وبــه حكمــت وبعــرض احلكــم علــى املدعــي العــام‬\n      ‫قــرر عــدم القناعــة وأجيــب لطلبــه كمــا قــرر أن الئحتــه االعتراضيــة‬\n      ‫مــا يف أوراق املعاملــة وأمــرت برفــع كامــل أوراق املعاملــة إلــى محكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية أغلقــت اجللســة يف متــام الســاعة الثامنــة‬\n      ‫وخمــس عشــرة دقيقــة وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                    ‫وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبحافظــة القطيــف بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبحافظــة القطيــف برقــم وتاريــخ ‪1434/03/01‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/03/01‬ه ـ ففــي يــوم‬\n      ‫الســبت ‪ 1434/06/03‬ه ـ افتتحــت اجللســة الرابعــة الســاعة ‪08 :30‬‬\n\n\n‫‪157‬‬\n\f‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫مبوجــب خطابهــم رقــم وتاريــخ ‪1434/05/27‬ه ـ واملقيــدة لدينــا‬\n‫برقــم وتاريــخ ‪1434/05/29‬ه ـ وبرفقهــا القــرار الصــادر مــن قضــاة‬\n‫محكمــة االســتئناف الدائــرة اجلزائيــة الثالثيــة األولــى ‪ -‬ج‪ 1/‬رقــم يف‬\n‫‪1434/05/15‬ه ـ واملتضمــن املصادقــة علــى احلكــم وبــه تعتبــر القضيــة‬\n‫منتهيــة وأغلقــت اجللســة يف متــام الســاعة ‪ 08 :45‬وصلــى اهلل علــى نبينــا‬\n                                         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪158‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":153,"source_page_end":158,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b94f94c34f782b7e29bf49d20a31b631a41a22e0e8c540abb1d45dec5d9d1ea5","normalized_text_hash":"bb82ae84095af038b4f9cb49fbcddae1a7fa5d8726f430a01ebc07bd592883cb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p153-34176751"}]$archive_payload$::jsonb AS data)
